import { installation } from './setup.mjs';
import { firstProgram, controlFlow, records, callbackPrimer, arrayPrimer, wgslPrimer, vertexPrimer } from './foundations.mjs';
import { p, section as s, code, note, table, list, snippet as q, frame, mistakes, experiments, diagrams as d, flow } from './html.mjs';
import { roomChapters } from './room-chapters.mjs';
import { animationChapter } from './animation-chapter.mjs';
export const chapters = [];
const chapter = (number, slug, part, title, deck, outcome, body) => chapters.push({number, slug, part, title, deck, outcome, body});

chapter(1, 'a-small-program', 'I · Establish the ground', 'Your first program and its tools',
  'Create a project, learn how to read its first Odin file, and check the libraries it will use.',
  'Your own project builds successfully and prints the SDL and WebGPU library versions.',
  s('The game we will build', p(`By the end of this book, you will control an animated character in a furnished room. The character will stop at walls and furniture. You will be able to resize the window and display the rectangles used for collision. We will build this application in small steps, explaining what each new piece makes possible.`)
  + p(`Odin runs the application. SDL3 creates the desktop window and reports input. WebGPU lets us draw using the graphics processor. We use wgpu-native, a library that implements WebGPU for desktop applications. A library is code our application calls to perform a task. Its application programming interface, or API, is the set of procedures and types we use to call it. Native means that our finished executable runs directly as a desktop application; this web page only displays the book. You do not need prior experience with these tools or with graphics programming.`)
  + p(`We will open a window, then draw a background color into it. We will add a triangle, turn it into a rectangle, and make it move. That rectangle teaches the drawing and movement rules we will reuse for the room artwork. Textures, collision, and animation each solve a limitation of the program we have at that point.`))
  + s('Create one working directory', p(`Open a terminal: Terminal on macOS/Linux, or PowerShell on Windows. Commands run relative to the terminal’s current directory. Choose a place for your work, then run these commands one line at a time. <code>mkdir</code> creates a directory; <code>cd</code> enters it.`)
  + code(`mkdir native-pixels-game
cd native-pixels-game
mkdir src
mkdir build`, 'shell', 'Start in the directory where you want to keep the project')
  + p(`Use a plain-text editor to create <code>main.odin</code> inside <code>src</code>. Check that the editor has not added a hidden <code>.txt</code> extension. All paths in the lessons are relative to <code>native-pixels-game</code>. Source files belong in src for now; compiled executables go in build. Keep using this same project as the chapters continue.`)
  + p(`All file paths are relative to <code>native-pixels-game</code>. A code block caption names the file and the part being discussed. Instructions above a focused excerpt say whether to add, replace, or read the code, name its enclosing procedure when needed, and identify the surrounding statements. Keep code outside the named replacement. A complete procedure replaces the existing procedure, including its body; do not append a second copy. Small syntax examples are marked as examples and do not become extra project files. The “Complete file with surrounding code” links lead to the full listing for this chapter, including its package line and imports. Use that listing whenever you want to check placement or replace the whole file.`))
  + firstProgram
  + s('Check the libraries before opening a window', p(`The first project file will print library versions instead of a greeting. This checks the installation before we add window or drawing code. A binding tells Odin which procedures a native library provides and how to call them. The matching library supplies their implementation. The compiler checks our Odin code, the linker connects its calls to libraries, and the operating system loads the executable and any shared libraries when it runs.`)
  + p(`The two vendor imports below provide the SDL and WebGPU bindings. The names <code>sdl</code> and <code>wgpu</code> are local names used before a dot, just as <code>fmt</code> is. <code>GetVersion()</code> is a call with no inputs. Its returned number becomes an input to the printing call. <code>wgpu.BINDINGS_VERSION_STRING</code> is a named value containing the binding’s expected version.`)
  + p(`Save this complete code in <code>src/main.odin</code>:`)
  + q(1, 'src/main.odin')
  + p(`<code>printf</code> prints using a format string. <code>%08x</code> displays an integer in base 16, using eight digits and leading zeroes; <code>0x</code> labels it as hexadecimal. The backslash-n at the end starts a new line. You do not need to calculate this number yourself: after installation, compare it with <code>0x1d000101</code>. SDL’s version number should be <code>3004016</code>, representing 3.4.16.`))
  + s('Install the matching tools', p(`Install Odin <code>dev-2026-09:a2fb372b7</code>, wgpu-native <code>29.0.1.1</code>, and SDL <code>3.4.16</code>. The following instructions include the downloads, library locations, and build commands. Read the common Odin and wgpu-native steps, then follow the SDL subsection for your operating system. You do not need to carry out the other platforms’ steps.`)
  + p(`These versions are a matched set for this edition. Native library calls depend on exact argument types and data layouts, so replacing only the WebGPU binary with a different version can break them. Internet access is needed to obtain these tools. Once they are installed and you have saved the book’s artwork, the project can be built offline.`))
  + installation
  + s('Run the first result', p(`The build command in your platform’s instructions reads <code>src</code> and writes the executable into <code>build</code>. Run that executable from the same terminal. It prints four lines and exits; no window should appear yet. The version procedures do not initialize a GPU, so a successful run proves installation and linkage, not graphics support.`)
  + p(`Keep the exact build command that worked for your platform. Use it after saving changes in each chapter, and then run the executable again. <code>-debug</code> includes debugging information; <code>-vet</code> enables extra compiler checks. If you open a new terminal, restore any PATH or SDL-prefix setting used by that command.`)
  + p(`For reference, SDL packs its version as major × 1,000,000 + minor × 1,000 + patch. WebGPU packs four components into four bytes: hexadecimal 1d is decimal 29, so 1d/00/01/01 represents 29.0.1.1. These formats explain why the two libraries print different-looking numbers.`))
  + mistakes([['The terminal cannot find odin', 'The PATH setting and the directory containing the compiler', 'The terminal must locate Odin before it can compile anything'], ['The linker cannot find a library', 'The library path in the platform instructions', 'Bindings describe calls but do not supply their implementation'], ['The executable cannot find SDL at launch', 'The DLL location on Windows or library search path on macOS/Linux', 'Loading happens after compilation and linking'], ['A version differs', 'Which compiler and native library your command selects', 'Another installation may be taking precedence']])
  + experiments(['Change the first printed message, rebuild, and run again. The changed output confirms that you are running the executable you just built.', 'Run the executable a second time without rebuilding. Explain which file the operating system executes and why editing source alone would not change that file.']));

chapter(2, 'a-window-belongs-to-sdl', 'I · Establish the ground', 'A window belongs to SDL',
  'Before an image can be presented, the operating system needs a window that stays responsive.',
  'A 960 × 640 desktop window opens and closes through the operating system’s normal controls.',
  controlFlow
  + s('Give SDL the window work', p(`SDL creates the window and passes us events from the operating system. Our loop reads those events so closing the window can stop the program. We will use WebGPU for drawing after this loop works. SDL also offers drawing APIs, but this program only uses its window and input facilities.`))
  + s('Replace the probe with a living window', p(`Replace <code>src/main.odin</code> in full. The program is short enough to see the entire lifetime before we divide it into graphics procedures.`)
  + q(2, 'src/main.odin')
  + p(`<code>sdl.Init({.VIDEO})</code> initializes the video subsystem and the event facilities it requires. SDL3 returns a boolean here: true means success. Older SDL2 examples often compare an integer result with zero. That check reverses the meaning if copied carelessly into SDL3. On failure, <code>GetError()</code> supplies a useful diagnostic.`)
  + p(`All calls that create, show, and destroy this window run from main. On macOS, the METAL flag lets SDL provide the kind of drawing surface the graphics library will need. Other supported desktop platforms do not need an extra graphics flag for this window. The ordinary window flags stay empty for now.`)
  + p(`CreateWindow gives us a window handle. ShowWindow asks the operating system to display it, and RaiseWindow asks to bring it forward. A system may refuse to give a background application focus, so a failed raise prints a message but leaves the program running. If showing the window fails, we return through cleanup.`)
  + p(`<code>CreateWindow</code> returns an SDL-owned opaque window object that our application must eventually destroy. SDL reads the quoted title as a C string, a sequence of characters with a zero byte marking its end. The string literal used here supplies the form SDL expects.`))
  + s('Events keep the window alive', p(`PollEvent reads one waiting event and writes it into event. The inner loop calls it until no events remain. An Event can hold data for several kinds of notification; its type field tells us which kind is present. This chapter only checks that field. A close or quit event sets running to false, and the outer loop then stops.`)
  + p(`<code>#partial switch</code> is intentional: SDL defines far more event types than we need. Ignoring an unrelated mouse motion does not mean it remains queued forever; polling has already removed it. A single <code>if PollEvent</code> per frame can leave a backlog during an event burst. Draining the queue gives us the latest state before updating the application.`)
  + p(`<code>Delay(10)</code> sleeps for roughly ten milliseconds so this empty loop does not consume an entire CPU core. It is temporary pacing, not a graphics clock. For now there is no drawing to wait for, so we pause explicitly between event checks. The native title bar and client area may appear blank, black, or platform-colored here. SDL has not drawn our background; this checkpoint makes no claim about client-area pixels.`))
  + s('Destruction follows dependency order', p(`The two <code>defer</code> statements establish reverse-order cleanup. The window is destroyed before SDL quits. An early return after a failed window creation still shuts down the successfully initialized subsystem. No failed handle is passed to its destroy function. The rule is to clean up a resource before the resource it depends on.`))
  + frame([['Initialize SDL and create window', 'Once', 'Acquire the native window resource'], ['Poll queued events', 'Every iteration', 'Keep the window responsive and observe close requests'], ['Destroy window, quit SDL', 'Once at shutdown', 'Release in reverse dependency order']])
  + mistakes([['Window stops responding', 'Whether the event loop is being pumped', 'The OS needs its window messages handled even without rendering'], ['Program exits immediately', 'A missing persistent loop, or a failing SDL3 boolean check', 'A window’s lifetime ends with the process'], ['macOS surface creation fails later', 'Main-thread window creation and the Metal window flag', 'The native rendering view must match the window’s platform requirements']])
  + experiments(['Change the title and dimensions, then observe that no WebGPU setup changes: neither exists yet.', 'Temporarily increase the delay to 250 ms. Closing the window becomes noticeably sluggish because the next event pump is delayed. Restore 10 ms.']));

chapter(3, 'triangles-become-pixels', 'I · Establish the ground', 'How triangles become pixels',
  'A draw describes geometry. The GPU determines which parts of an image that geometry covers.',
  'The SDL window from chapter 2 remains the runnable checkpoint; no code changes in this mental-model chapter.',
  s('A rectangle needs corners, not a list of pixels', p(`Imagine drawing a filled rectangle on squared paper. You can describe it by marking four corners; you do not have to name every square inside it. A graphics program can make the same kind of description. A vertex is a record describing a corner or another point in a shape. A pixel is one element of the output image’s grid.`)
  + p(`We will draw filled shapes as triangles. Three corners define one triangle. Four rectangle corners can be used by two triangles, as the diagram shows. The numbers label the corners; each group of three numbers selects one triangle. This arrangement lets the triangles share two corners.`)
  + d.quad
  + p(`The diagonal divides the work between the triangles. It is not a line we ask the GPU to draw. The GPU’s edge rules determine which triangle covers each sample along that shared edge, so together the triangles fill the rectangle.`))
  + s('Follow a triangle into the image', p(`The GPU processes our description in stages. A shader is a small program that runs on the GPU. We will write one shader to place vertices and another to choose colors. The sequence of these programs and the fixed work between them is a graphics pipeline.`)
  + flow('The GPU turns corners into a colored region.', ['Place vertices', 'Assemble triangles', 'Find covered samples', 'Calculate color', 'Write the image'])
  + p(`First, the vertex shader calculates where each corner belongs. The GPU groups those corners into triangles. It clips away any parts outside the visible area, then finds which image sample locations the remaining triangles cover. Finding that coverage is called rasterization.`)
  + p(`Rasterization produces fragments: candidates for color contributions to the image. The fragment shader chooses a color for each contribution. A fragment is not the same thing as a final visible pixel: another triangle may later write the same location. For now, imagine one triangle over a background, so its covered region receives the shader’s chosen color.`)
  + p(`The vertex shader does not call the fragment shader. It returns positions. The GPU uses those positions to create the fragment work. This is why changing how a face is colored need not require adding more corners to the rectangle.`))
  + s('Recording work is different from doing it', p(`Our Odin application runs on the CPU. It describes the drawing work and sends that work to the GPU. A draw call records an instruction; it does not wait until the monitor shows the result. The GPU can draw an earlier frame while the CPU prepares a later one.`)
  + p(`We will use a command encoder to build a list of instructions. Finishing the encoder produces a command buffer: the completed list. Submitting gives that list to the device’s queue for execution. Presenting hands the resulting image to the window system for display. We will implement these steps individually when the window connection is ready.`)
  + d.pipeline
  + p(`Keep two questions separate as you read the next chapters: “Have we described the work?” and “Have we submitted it for execution?” A correct triangle description cannot change the window until it reaches the GPU and its image is presented.`))
  + s('Keep the current program working', p(`There are no file changes in this chapter. Build and run the same window as before. Close it through its title bar. It should still respond, and it still has no background drawn by our code.`)
  + p(`You now know what our drawing code will ask the GPU to do. We need a connection between WebGPU and the window before we can send those instructions. That is the purpose of the next chapter.`))
  + frame([['Describe a shape', 'Before drawing', 'A few corners can describe a large filled region'], ['Record and submit commands', 'For each future frame', 'Give the GPU work to execute'], ['Poll SDL events', 'In the current program', 'Keep the window responsive while it remains open']])
  + mistakes([['Treating a vertex as a pixel', 'Whether the value describes a corner or an output image element', 'Three vertices can describe a triangle covering many pixels'], ['Assuming a draw call means drawing is finished', 'Whether commands have been submitted and an image presented', 'Recording and execution are separate steps']])
  + experiments(['Sketch a rectangle and label its corners 0 through 3. List the corners of the two triangles that fill it.', 'Sketch two overlapping triangles. Choose a color for each and predict which color is visible in the overlap when the second triangle replaces the first there.']));

chapter(4, 'instance-and-surface', 'II · Put pixels on the window', 'Instance and surface',
  'Connect WebGPU to the window that SDL created.',
  'The window has a WebGPU instance and surface. It stays responsive, but our program has not drawn an image yet.',
  records
  + s('A connection before a device', p(`A WebGPU instance is our starting object for the native graphics library. It lets us create a surface for the existing window. Create the instance once and keep it until cleanup has released the surface. The name “instance” here means this library context, not an extra copy of a character.`)
  + p(`A surface identifies the window destination that WebGPU will present images to. Creating the surface connects the graphics library to that destination. It does not draw a frame or choose the image dimensions yet. We will make those choices after creating a device.`)
)
  + s('Give the connection an explicit owner', p(`We need two related structs. Platform_Surface keeps the surface handle and, on macOS, the extra view created through SDL. Add that struct to the new src/platform.odin file. GPU then keeps the instance and the Platform_Surface together. Add GPU and its procedures to the new src/gpu.odin file. All three Odin files still use package character and compile together.`)
  + q(4,'src/platform.odin','Platform_Surface ::')
  + q(4,'src/gpu.odin')
  + p(`<code>CreateInstance(nil)</code> asks for the implementation’s default instance configuration. In this binding the small wrapper checks the linked wgpu-native version before calling the native entry point. We do not request special backend extensions. A descriptor would be useful for nondefault instance requirements, but a pointer to an empty descriptor is not more educational than a deliberate default.`)
  + p(`Inside <code>main()</code>, add a local <code>gpu: GPU</code> after window creation. Register <code>defer gpu_destroy(&gpu)</code> before calling initialization so partial failure is cleaned up. Then return if <code>gpu_init(&gpu, window)</code> fails. The window’s earlier defer will run after the GPU cleanup. The complete changed main appears in this chapter’s file listings.`))
  + s('Why descriptors have a chain', p(`The ordinary SurfaceDescriptor contains a label and a nextInChain pointer. Window systems need different extra information, so this pointer selects a second descriptor holding the platform-specific fields. Its sType field identifies their type. For macOS we use SurfaceSourceMetalLayer; the fields then include a pointer to the layer. Both descriptors are ordinary structs on the CPU.`)
  + p(`InstanceCreateSurface reads the two descriptors during the call. They may be local variables because we need their values only during that call. The returned surface has a longer lifetime. The native window and layer must also remain alive for as long as the surface uses them. Temporary settings and the objects described by those settings have different lifetimes.`))
  + s('The bridge is ordinary Odin', p(`Finish src/platform.odin with the creation and cleanup procedures in this chapter’s full listing. Read the branch for your operating system first. Each branch obtains the native object that WebGPU expects, describes its type, and calls InstanceCreateSurface. The macOS example below shows that sequence.`)
  + q(4,"src/platform.odin","    when ODIN_OS == .Darwin {"," else when ODIN_OS == .Windows {","src/platform.odin · platform_surface_create · macOS branch","Inside platform_surface_create, this is only the macOS branch, ending before else when ODIN_OS == .Windows. Keep the Windows and Linux branches and the surrounding procedure; use the complete file when creating this new platform bridge.")
  + p(`On macOS, SDL creates a Metal-capable view and returns its underlying <code>CAMetalLayer</code>. That layer is the object a Metal-backed WebGPU surface can present into. It is obtained through SDL’s C ABI, so we need no Objective-C or C helper. We retain the <code>MetalView</code> handle and destroy it only after releasing the WebGPU surface. An <code>NSWindow</code> pointer by itself is not the Metal layer.`)
  + table(['Platform', 'SDL query or object', 'WebGPU chained descriptor'], [['macOS', '<code>Metal_CreateView</code> → <code>Metal_GetLayer</code>', '<code>SurfaceSourceMetalLayer</code>'], ['Windows', '<code>PROP_WINDOW_WIN32_HWND_POINTER</code> and instance property', '<code>SurfaceSourceWindowsHWND</code>'], ['Linux / Wayland', 'Display pointer and wl_surface pointer properties', '<code>SurfaceSourceWaylandSurface</code>'], ['Linux / X11', 'Display pointer and numeric X11 window identifier', '<code>SurfaceSourceXlibWindow</code>']])
  + p(`SDL3 exposes these values through <a href="https://wiki.libsdl.org/SDL3/SDL_GetWindowProperties">window properties</a>. This replaces recipes based on SDL2’s SysWM information structs. On Linux we inspect SDL’s actual video driver before choosing a descriptor: X11 and Wayland handles are not interchangeable. A headless or dummy SDL driver has no supported desktop surface here and is rejected with a diagnostic.`))
  + s('Release the surface before its window', p(`The surface refers to the native window or layer. Release the surface first, then any Metal view, and finally the SDL window. Reset the owner to an empty struct after releasing its handles.`)
  + q(4,'src/platform.odin','platform_surface_destroy ::')
  + note('Native versus JavaScript', 'Browser WebGPU receives a canvas context from the browser. It does not expose Win32, X11, Wayland, or Metal-layer descriptor chains. The native surface fills the equivalent presentation role, with explicit host ownership.'))
  + frame([['Instance creation', 'Once', 'Enter the native WebGPU implementation'], ['Native view and surface creation', 'Once per window', 'Wrap a platform presentation destination'], ['Descriptor locals', 'During each creation call', 'Input metadata; not persistent graphics objects']])
  + mistakes([['Null surface', 'Native handles and the matching sType', 'The implementation needs a specific supported presentation object'], ['Crash on shutdown', 'Surface → view → window destruction order', 'The surface must not refer to a destroyed native window'], ['A window exists but stays blank', 'Expected at this stage', 'This chapter has connected the window; it has not drawn an image']])
  + experiments(['Print the chosen SDL video driver on Linux and locate its corresponding surface branch.', 'Trace which defers run if surface creation fails after the instance succeeds. Confirm that the Metal view, if created, is still released.']));

chapter(5, 'adapter-device-queue', 'II · Put pixels on the window', 'Adapter, device, and queue',
  'Choose an adapter that can use our window, then create its device and queue.',
  'The window opens with a compatible adapter, device, queue, and diagnostic callbacks installed.',
  s('Three names for three different decisions', p(`An adapter represents a candidate graphics implementation with particular capabilities. It often corresponds to a physical GPU, but may instead be a software implementation. A laptop can offer more than one adapter. A surface-compatible adapter must be able to present to our chosen window, so we create the surface first and include it in the adapter request.`)
  + p(`A device is a logical connection created from an adapter. It owns our buffers, pipelines, and command encoders. The adapter describes what is available; the device establishes what this application is allowed to use. Requesting features and limits is a contract, not a way to manufacture hardware support. Our rectangle needs only baseline functionality, so the device descriptor leaves required features empty and required limits absent.`)
  + p(`The queue accepts data uploads and drawing work for the device. It keeps that work in order. We obtain it once with <code>DeviceGetQueue</code> and hold our returned reference until shutdown. Do not create a queue every frame; the ordered stream is exactly what lets this frame’s buffer write precede this frame’s draw.`))
  + callbackPrimer
  + s('A request has a result callback', p(`In src/gpu.odin, add imports for base:runtime and base:intrinsics alongside the existing imports. Extend GPU with adapter, device, and queue handles and the adapter_done and device_done booleans. The complete declaration below shows their types. Each request callback stores its result and sets its completion flag. The request helper then checks those fields before going on.`)
  + q(5,'src/gpu.odin','GPU ::')
  + table(['Descriptor field', 'What we are asking for'], [['<code>compatibleSurface</code>', 'An adapter whose backend can present to this surface'], ['<code>powerPreference</code>', 'A preference for performance; not a guarantee of a discrete GPU'], ['<code>featureLevel = .Core</code>', 'The core WebGPU feature level'], ['<code>defaultQueue.label</code>', 'A diagnostic name for the device’s queue'], ['Required features / limits omitted', 'The native implementation’s baseline device contract'], ['Callback info', 'Function pointer, delivery policy, and caller-owned result storage']])
  + note('The exact native implementation matters', `The pinned wgpu-native 29.0.1.1 implementation invokes both request callbacks inside their request functions and completes them before returning. The assert checks each completion flag and stops if this version-specific assumption is broken. <code>.AllowSpontaneos</code> is the Odin binding’s exact spelling. Recheck callback timing before changing the native library version.`, 'warning'))
  + s('Odin meets the callback ABI', q(5,'src/gpu.odin','adapter_ready ::')
  + p(`<code>proc "c"</code> matches the native calling convention. The callback sets <code>runtime.default_context()</code> before printing, as described in the callback example. The <code>userdata1</code> pointer is the exact <code>gpu</code> pointer we supplied; it gives the callback somewhere to store the owned returned handle. The callback’s message is borrowed text. We print it during the callback instead of retaining a pointer to memory the implementation may immediately free.`)
  + p(`The device callback is structurally similar, except that it receives a device handle and stores <code>device_done</code>. A failed adapter request can mean missing drivers, no compatible backend, or a surface that the available adapter cannot present to. A failed device request can mean unsupported requirements or a failure to establish the backend device. Both log the native status and message before initialization returns false.`)
  + q(5,'src/gpu.odin','uncaptured_error ::')
  + p(`Install uncaptured-error and device-loss callbacks in the device descriptor before any resources are created. Validation errors are often reported through a callback, not merely as a null handle. Our callbacks report the message and atomically set a process-lifetime <code>gpu_fault</code> flag. Diagnostic delivery may occur on another thread; unlike the pinned inline request-result fields, this flag cannot safely use ordinary unsynchronized access. Process-lifetime storage also avoids a callback holding a pointer into a destroyed renderer.`)
  + p(`At the top of each iteration after SDL event processing, call <code>InstanceProcessEvents</code>, then check <code>gpu_failed()</code>. This services native completion work; it is not a command submission and does not wait for every GPU operation. On device loss we stop, release our objects, and let the user restart. Rebuilding every device-dependent resource is outside this small project’s scope, but detecting and explaining loss is not optional.`))
  + s('Request the adapter, then the device', p(`Add gpu_request_device to src/gpu.odin. In gpu_init, replace the final return true with return gpu_request_device(gpu). The adapter request includes our surface. After its callback succeeds, the device request installs error reporting and requests a queue. No optional features or larger-than-default limits are required.`)
  + q(5,'src/gpu.odin','gpu_request_device ::')
  + p(`Read the helper from top to bottom. First it asks for a compatible adapter and checks that adapter_ready ran. Then it creates the device descriptor and asks the adapter for a device. Finally it obtains the queue and returns true only if the queue exists and no error callback has set the fault flag. A failure returns through the cleanup already registered in main.`))
  + s('We own references, not raw hardware', p(`Add release calls for queue, device, and adapter to <code>gpu_destroy</code>. It first calls the native extension <code>DevicePoll(device, true, nil)</code> to drain outstanding work at shutdown. There is no such blocking call in the normal frame loop. Release decrements the application’s reference; it does not necessarily destroy an underlying allocation at that instant. Related objects and in-flight work can retain what they need.`))
  + frame([['Request adapter and device', 'Once', 'Select and establish the application’s GPU connection'], ['Get queue', 'Once per device', 'Hold the ordered submission stream'], ['Process native events', 'Each iteration', 'Service callbacks without a per-frame full GPU wait'], ['Blocking DevicePoll', 'Shutdown only', 'Drain work during orderly teardown']])
  + mistakes([['Crash inside a logging callback', 'Calling convention and Odin context', 'A native caller does not supply Odin context'], ['Device handle exists but resource creation fails', 'The uncaptured-error message', 'A non-null handle is not a complete validation check'], ['Request result appears empty in another implementation', 'Whether completion was actually delivered', 'The inline behavior is pinned implementation behavior, not a portable promise']])
  + experiments(['Change the adapter power preference to <code>.LowPower</code>. The program may choose the same adapter; explain why a preference need not change the result.', 'Follow the code path when the adapter callback reports failure. Which objects still require release?']));

chapter(6, 'negotiate-the-images', 'II · Put pixels on the window', 'Negotiate the images',
  'Ask which image settings the window supports, then choose the size and format to use.',
  'The surface is configured with a supported sRGB format, FIFO presentation, and actual drawable dimensions.',
  s('A surface is a negotiation point', p(`The instance created the surface independently of the device. We now join them. Capabilities describe choices supported by this surface and adapter pair: color formats, texture usages, presentation modes, and compositing-alpha modes. Querying the adapter alone is insufficient; the display system and window backend also constrain presentation.`)
  + p(`An image stores a number for each color channel. A byte contains eight bits and can represent 256 different unsigned values, from 0 to 255. BGRA8UnormSrgb stores one byte each for blue, green, red, and alpha. Unorm maps those stored values to the range 0 to 1. Alpha describes opacity for a chosen composition rule; our window will remain opaque. The shader still writes red, green, blue, and alpha in that order. The format handles their storage order.`)
  + p(`sRGB describes how RGB values are encoded for storage and display. Our shader and clear values represent linear light: twice the value means twice the light contribution. The sRGB surface converts those linear RGB values to its storage encoding. Alpha is not sRGB-encoded. We select a supported RGBA or BGRA sRGB format and stop with an error if neither exists, so the program always uses the same color interpretation.`))
  + arrayPrimer
  + s('Read, select, then release the capability lists', p(`Add <code>gpu_choose_surface</code> to <code>gpu.odin</code>. In <code>gpu_init</code>, call it after <code>gpu_request_device</code> succeeds. The selected values are copied into <code>gpu.config</code>; the native capability arrays are freed before the function returns.`)
  + q(6,'src/gpu.odin','gpu_choose_surface ::')
  + p(`<code>SurfaceGetCapabilities</code> is a small Odin convenience wrapper over a native output-pointer call. It returns a struct and status. Inside the struct, arrays are still native pointer/count pairs. Slicing <code>caps.formats[:caps.formatCount]</code> creates a temporary Odin view over those elements; it does not transfer ownership. <code>SurfaceCapabilitiesFreeMembers</code> is the matching native deallocator. Do not call Odin <code>delete</code> on those pointers or retain the slices after freeing them.`)
  + p(`FIFO means first in, first out: images are presented in the order submitted, paced by the display system. It is the baseline mode, and our code still checks that the surface advertises it. Returning from a present call does not tell us the exact instant the monitor shows an image; the operating system may still be scheduling it.`)
  + p(`Surface composite alpha controls how the window image is combined with the desktop. It is separate from blending a character over its background inside our render pass. We select opaque compositing if listed, otherwise use the implementation’s automatic policy. Our clear alpha is one, so the complete window image remains opaque. <code>.Auto</code> is a valid selection even though capability lists do not enumerate it.`))
  + s('Configuration is a contract for future acquisitions', table(['Surface configuration', 'Meaning in our program'], [['Device', 'Which logical device will render these images'], ['Format', 'The render pipeline’s color target must match this format'], ['Usage = RenderAttachment', 'We will attach the acquired texture to a render pass'], ['Width and height', 'Actual framebuffer dimensions in physical pixels'], ['Present mode', 'How completed images are scheduled for presentation'], ['Alpha mode', 'How the window image participates in desktop compositing']])
  + p(`A usage flag declares which operations a resource may be used for. RenderAttachment permits drawing into the image as a render-pass output. This is all the surface needs here. If we try an operation that was not permitted when configuring the resource, WebGPU can report a validation error: a message that an API rule was broken.`)
  + p(`Add <code>gpu_refresh_surface</code>. The initial call happens in <code>gpu_init</code>. We query <code>GetWindowSizeInPixels</code>, because configuration dimensions describe the image, not necessarily SDL’s logical window units. A zero width or height is not a legal rendering configuration. We skip it and try later. We also reject an extent larger than the device’s <code>maxTextureDimension2D</code> rather than issuing a predictably invalid configure call.`)
  + q(6,'src/gpu.odin','gpu_refresh_surface ::')
  + p(`The stored descriptor is application-owned CPU data. <code>SurfaceConfigure</code> consumes its values and manages the presentable images internally. The <code>configured</code> flag records whether this application successfully established a usable configuration; <code>dirty</code> requests reconfiguration even if dimensions are unchanged. We will set dirty when acquisition reports an outdated or suboptimal surface. Calling this helper every frame later does not mean calling <code>SurfaceConfigure</code> every frame: its comparison gates the expensive operation.`)
  + note('Configuration does not draw', 'The window may still show an undefined-looking client area. We have selected the properties of future frame images, but have not acquired, cleared, or presented one. Surface creation and surface configuration are two separate milestones.'))
  + frame([['Capability query and selection', 'Initialization', 'Select supported values for this adapter/surface pair'], ['Configure extent', 'Initially and when dirty or size changes', 'Presentable images must match the drawable'], ['Capability memory free', 'After selection', 'Lists belong to the native allocator'], ['Unconfigure', 'Shutdown', 'Detach configured presentation resources']])
  + mistakes([['Validation error while configuring', 'Usage, format, nonzero extent, and device limit', 'A descriptor is a set of promises checked together'], ['Color looks unexpectedly bright or dark', 'sRGB versus linear output assumptions', 'A storage format has color-interpretation semantics'], ['Crash while reading formats later', 'Whether capability members were already freed', 'The pointer/count lists are borrowed only until native deallocation']])
  + experiments(['Print all advertised formats before selecting one. Identify which names differ only by the sRGB suffix.', 'Make the initial window much smaller. The configuration dimensions should change; the chosen adapter and format usually should not.']));

chapter(7, 'one-clear-frame', 'II · Put pixels on the window', 'One clear frame',
  'Before drawing geometry, make the entire presentation path prove itself with one background color.',
  'A dark blue background fills the native window through WebGPU alone.',
  s('An image for this frame', p(`An acquired surface texture is a handle to the image the presentation system currently makes available for rendering. The implementation manages a set or sequence of presentable images behind the surface. It may rotate backing images or wait until one becomes available. We do not cache the texture from the previous iteration: presentation ends that image’s role as our current render target.`)
  + p(`A texture holds image storage. A texture view describes the part of that storage a graphics operation can access. Our render pass uses a view covering the whole acquired image. TextureCreateView(texture, nil) requests that default view. The view is a separate handle with its own release.`)
  + table(['Object', 'Where its meaning lives', 'Application reference lifetime'], [['Acquired texture', 'GPU image plus presentation bookkeeping', 'One frame'], ['Texture view', 'CPU/backend access metadata referring to that image', 'One frame'], ['Encoder', 'CPU-side mutable command recording', 'One frame'], ['Render pass encoder', 'Recording scope for attachment operations', 'One pass'], ['Command buffer', 'Finished backend command sequence', 'Until submitted, then our reference can release']]))
  + s('Add a renderer with no geometry yet', p(`Add <code>src/renderer.odin</code> and its <code>renderer_frame</code> procedure. In <code>main</code>, replace the final <code>sdl.Delay(10)</code> with <code>if !renderer_frame(&gpu, window) { break }</code>. Each call now prepares and presents one complete image. The complete procedure is in this chapter’s source; we will read its three sections in order.`)
  + q(7,"src/renderer.odin","    if !gpu_refresh_surface","    encoder :=","src/renderer.odin · renderer_frame · acquire and view","Begin the body of the new renderer_frame procedure with this block. The next block starts at encoder :=. Copy the procedure signature and imports from the complete file.")
  + p(`The refresh happens before acquisition so no old frame handle is live during reconfiguration. On optimal success we proceed. Suboptimal success still supplies a usable image; we render it and schedule reconfiguration for the next frame. Timeout or occlusion means skip briefly. Outdated means schedule reconfiguration and retry on a later iteration. Lost means the surface connection itself is no longer usable; our small program logs this and exits rather than endlessly retrying a broken connection. Generic acquisition errors are fatal here.`)
  + p(`The deferred texture release is installed before examining the status. That guarantees cleanup for any returned handle, including unusual error paths. The view gets its own release because it is a distinct native reference. Returning from this procedure releases the frame-local objects before the next call can reconfigure the surface.`))
  + s('Describe the pass, then record it', q(7,"src/renderer.odin","    encoder :=","    wgpu.RenderPassEncoderEnd(pass)","src/renderer.odin · renderer_frame · begin recording","Inside renderer_frame, continue immediately after defer wgpu.TextureViewRelease(view). This block ends just before wgpu.RenderPassEncoderEnd(pass), which appears in the next snippet.")
  + p(`Creating the command encoder allocates a recording object. The GPU has not received a draw or clear yet. The attachment descriptor says which view receives color output, how existing contents are treated, and whether results must be preserved. <code>loadOp = .Clear</code> initializes the entire attachment with our background. <code>storeOp = .Store</code> preserves the result for presentation. Loading previous contents would be meaningless for this fully redrawn frame, and discarding the result would defeat presentation.`)
  + p(`Set depthSlice to DEPTH_SLICE_UNDEFINED because this is a 2D image, not one slice of a 3D texture. This named value matters: a zero-filled descriptor does not automatically mean “use every default.” Leave resolveTarget and the depth/stencil fields absent because this pass writes only one ordinary color image.`)
  + p(`The pass descriptor passes the address of one color-attachment descriptor and a count of one. These are the pointer-and-count fields we learned in chapter 6. They stay valid while CommandEncoderBeginRenderPass reads them. The returned pass encoder keeps the information needed for recording. The clear operation gives this pass useful work even before we add draw calls.`))
  + s('Finish, submit, present', q(7,"src/renderer.odin","    wgpu.RenderPassEncoderEnd(pass)","\n}\n","src/renderer.odin · renderer_frame · final statements","Inside renderer_frame, append these final statements after defer wgpu.RenderPassEncoderRelease(pass), then close the procedure with its existing closing brace.")
  + p(`<code>RenderPassEncoderEnd</code> closes the pass’s recording scope. It does not release the pass handle. <code>CommandEncoderFinish</code> closes the whole encoder and returns a command buffer. We cannot keep appending draws to that finished recording. The one-element slice passed to <code>QueueSubmit</code> is adapted by the binding to the native count/pointer pair. We submit that command buffer once.`)
  + p(`The queue now has work that depends on the acquired image. <code>SurfacePresent</code> hands the current image back for display through the window system after its rendering dependencies. It is a separate native call; browser presentation is integrated with canvas/browser scheduling. Submit is not present, and present is not a guarantee that the monitor has already scanned out the image.`)
  + p(`Defers run in reverse order: command buffer, pass encoder, command encoder, texture view, texture. Releasing our native command-buffer reference immediately after submission is correct: submitted work retains the backend resources it requires. We are not synchronously freeing memory that the GPU is about to read. A release is an ownership operation, not a completion fence.`))
  + s('Use this clear as a diagnostic boundary', p(`We now know whether the surface connection, configuration, acquisition, command recording, queue submission, and presentation work together. Later, if the background appears but the character does not, we can begin the search in geometry, pipeline, bindings, or shader code. That does not prove every presentation path is infallible, but it removes a large part of the startup chain from the first hypothesis.`))
  + frame([['Refresh check', 'Every frame; configure only when needed', 'Ensure the next acquired extent is correct'], ['Texture, view, encoder, pass, command buffer', 'Every rendered frame', 'Record work against this frame’s image'], ['Submit and present', 'Every rendered frame', 'Make work available and schedule its output'], ['Pipeline creation', 'Not yet', 'A clear operation needs no shader pipeline']])
  + mistakes([['Window stays black or unchanged', 'Use a bright red clear color; verify submit and present', 'A pass that never reaches the queue cannot change the image'], ['Validation mentions attachment contents', 'StoreOp and loadOp', 'Presentation needs a preserved result'], ['Memory grows every frame', 'All five frame-local release paths', 'Reference leaks accumulate even when the window looks correct']])
  + experiments(['Set <code>clearValue</code> to opaque red. There is no fragment shader yet; explain why the image can still become red.', 'Temporarily omit <code>QueueSubmit</code>, observe the result, then restore it. Treat the observed image as backend-dependent; the missing submission itself is the decisive evidence.']));

chapter(8, 'the-first-triangle', 'II · Put pixels on the window', 'The first triangle',
  'Write two small shaders and use them to draw a triangle over the background.',
  'A green triangle appears over the dark background, with no vertex buffer yet.',
  wgslPrimer
  + s('Start with the smallest possible shader input', p(`We already have a valid render pass. It needs a pipeline and a draw. To avoid introducing buffer layout and shader syntax simultaneously, the first vertex shader keeps three positions in a constant WGSL array. The GPU supplies a built-in vertex index. Drawing three vertices invokes the shader for the three entries and assembles their outputs into one triangle.`)
  + p(`Add <code>shaders/character.wgsl</code>. The name anticipates its role later; today it is a triangle shader. WGSL is compiled by the native implementation into the backend shader language or machine representation it needs. There is no separate browser runtime and no need for us to write a Metal or HLSL version.`)
  + q(8,'shaders/character.wgsl')
  + p(`<code>@vertex</code> identifies the vertex entry point. <code>@builtin(vertex_index)</code> requests an input generated by the draw machinery rather than loaded from our vertex buffer. The returned <code>@builtin(position)</code> is the clip position the rasterizer needs. Its z=0 and w=1 keep our 2D triangle inside WebGPU’s depth clip interval and make clip x/y equal NDC x/y.`)
  + p(`<code>@fragment</code> marks the fragment entry point. Its <code>@location(0)</code> output goes to color target zero. This location is not a pixel coordinate, a bind-group binding, or a buffer slot. Shader interfaces have distinct namespaces that we will keep separate as the program grows. The constant RGBA color is linear-light green with alpha one.`))
  + s('A module is code; a pipeline is a configured program', p(`Extend <code>renderer.odin</code> with a <code>Renderer</code> struct containing the pipeline handle, plus <code>renderer_init</code> and <code>renderer_destroy</code>. In <code>main</code>, initialize this renderer after GPU setup and register its cleanup. Pass the renderer pointer into <code>renderer_frame</code>. These are related changes: a persistent resource needs an owner and a way to reach its per-frame use.`)
  + q(8,"src/renderer.odin","    source :=","    target :=","src/renderer.odin · renderer_init · module and empty pipeline layout","Inside the new renderer_init procedure, place this block at the beginning of its body, before target :=. The complete file supplies the procedure signature.")
  + p(`<code>#load</code> embeds the shader text at compile time relative to the Odin source file. The executable does not depend on its working directory to find a shader. Editing WGSL requires rebuilding; there is no hot reload. The <code>ShaderSourceWGSL</code> extension uses the same descriptor-chain mechanism we saw for native surfaces, with a discriminator telling WebGPU how to interpret its source.`)
  + p(`A shader module can contain several entry points. Creating it parses and validates source, while pipeline creation also checks stage interfaces and target compatibility and may perform expensive backend compilation. The pipeline keeps the implementation data it needs; we can release our shader-module handle after creation. Error callbacks remain essential because an invalid shader can produce an error object even when the handle is not nil.`)
  + p(`A pipeline layout describes resource inputs supplied to shaders. A bind group is a set of those inputs. This shader uses only its own fixed values, so its layout has zero bind groups. Creating an empty layout records that choice explicitly.`))
  + s('Read the descriptor from the outside inward', flow('A render pipeline combines shader stages with fixed rendering state.', ['Vertex stage', 'Primitive rules', 'Fragment stage', 'Color / blend', 'Resource layout'])
  + q(8,"src/renderer.odin","    target :=","    renderer.pipeline =","src/renderer.odin · renderer_init · complete pipeline descriptor inputs","Inside renderer_init, continue after defer wgpu.PipelineLayoutRelease(layout). These descriptor declarations go immediately before renderer.pipeline = wgpu.DeviceCreateRenderPipeline; keep that creation call and its success check from the complete file.")
  + table(['Piece', 'Decision'], [['Vertex module / entry point', 'Run <code>vs_main</code>; no buffer input yet'], ['Primitive topology', 'TriangleList groups each three vertex references'], ['Front face / culling', 'CCW is designated front, but <code>None</code> culls neither face'], ['Fragment target', 'Run <code>fs_main</code>; its output zero matches target zero'], ['Target format', 'Exactly the configured surface format'], ['Write mask', 'Enable all four color channels'], ['Blend pointer nil', 'Replace the target color with the shader output'], ['Multisample', 'One sample, all bits enabled in its mask'], ['Depth/stencil absent', 'No depth attachment or depth comparison']])
  + p(`The pipeline knows the target format because output conversion and blending must be valid for that format. A floating-point shader result cannot be written under arbitrary target assumptions. This also lets the implementation compile state before the frame is recorded. It does not know this frame’s texture handle or window size. Those are render-pass and viewport concerns, which is why resizing alone will not require a new pipeline.`))
  + s('A draw finally appears', code(`wgpu.RenderPassEncoderSetPipeline(pass, renderer.pipeline)
wgpu.RenderPassEncoderDraw(pass, 3, 1, 0, 0)`, 'odin', 'src/renderer.odin · renderer_frame · add immediately before RenderPassEncoderEnd')
  + p(`The draw arguments are vertex count, instance count, first vertex, and first instance. We need three vertices and one instance, starting at zero. Selecting the pipeline establishes the executable state for subsequent draw commands in this pass. It does not itself render. The draw is still only a recorded command until the command buffer reaches the queue.`)
  + p(`When executed, the vertex shader emits three clip positions; clipping and rasterization find the triangle’s covered samples; the fragment shader returns green for them; the color target writes those values into the same image that was cleared blue. One pass now performs both the background clear and the triangle draw.`))
  + frame([['Shader module, layout, pipeline', 'Renderer initialization', 'Validate and compile stable state once'], ['Set pipeline and draw', 'Once per frame in this program', 'Record geometry against the acquired attachment'], ['Module/layout application references', 'Released after pipeline setup', 'Persistent objects retain necessary backend dependencies']])
  + mistakes([['Background visible, triangle missing', 'Coordinates, draw count, pipeline binding, validation log', 'The clear path works independently of the draw path'], ['Pipeline error mentions target format', 'Compare descriptor target with gpu.config.format', 'Pass attachment and pipeline output contract must agree'], ['Nothing drawn with no obvious shader error', 'Write mask and multisample count/mask', 'An accidentally zeroed field can disable output or invalidate state']])
  + experiments(['Change one vertex x coordinate beyond +1. Observe clipping rather than assuming the entire triangle disappears.', 'Change the fragment output to red. Compare how this differs from changing the pass clear color.', 'Move all vertex z values to −1, observe clipping, then restore zero. Depth clipping applies even without a depth test.']));

chapter(9, 'vertex-bytes', 'III · Build a small 2D renderer', 'Vertex bytes become shader inputs',
  'A buffer is bytes. Its layout is the agreement that turns those bytes into positions and colors.',
  'The triangle reads an Odin-created vertex buffer and interpolates three corner colors.',
  vertexPrimer
  + s('Move geometry out of the shader', p(`The hard-coded array proved the shader pipeline. It becomes awkward as soon as geometry belongs to the application rather than to shader source. A GPU buffer gives us a persistent region of bytes usable by GPU operations. The CPU owns a native handle, while the implementation chooses suitable backing storage. We cannot assume that storage is an ordinary CPU array, even on a machine with unified memory.`)
  + p(`Add the <code>Vertex</code> struct and three-element <code>VERTICES</code> constant to <code>renderer.odin</code>. The constant is CPU-side data compiled into the program. The WebGPU buffer created from it is a separate object. Change the WGSL vertex entry point to read attributes rather than <code>vertex_index</code>. This deliberately removes the temporary shader array introduced in chapter 8.`)
  + q(9,"src/renderer.odin","Vertex ::","Renderer ::","src/renderer.odin · add vertex ABI, assertions, and initial data","At file scope, insert Vertex, its assertions, and VERTICES immediately before Renderer. Keep the package/import lines and existing procedures.")
  + d.memory)
  + s('Follow one record through all three interfaces', table(['Odin memory', 'WebGPU attribute', 'WGSL input'], [['Bytes 0–7: two f32 position values', 'Offset 0, Float32x2, location 0', '<code>@location(0) position: vec2f</code>'], ['Bytes 8–23: four f32 color values', 'Offset 8, Float32x4, location 1', '<code>@location(1) color: vec4f</code>'], ['Next record begins 24 bytes later', 'arrayStride = 24, stepMode = Vertex', 'A new record for the next vertex index']])
  + p(`The stride is the distance in bytes from the beginning of one vertex record to the beginning of the next. An attribute’s offset is measured from the beginning of its record. The GPU effectively reads <code>buffer_base + vertex_number × stride + attribute_offset</code>, then interprets those bytes according to the format. The shader location identifies the destination parameter; the parameter’s name is not part of this matching process.`)
  + p(`Our struct contains arrays of scalar f32 values. Its position begins at byte zero and its color at byte eight, with size 24. Compile-time assertions make that ABI explicit. These assertions check the actual record layout instead of assuming that the compiler arranged it as we expected.`)
  + q(9,"src/renderer.odin","    attributes :=","    descriptor :=","src/renderer.odin · renderer_init · add vertex fetch layout","Inside renderer_init, insert these two declarations immediately before descriptor := wgpu.RenderPipelineDescriptor. Also add bufferCount = 1 and buffers = &vertex_layout to descriptor.vertex, as shown in the complete file.")
  + p(`<code>attributeCount</code> and <code>attributes</code> describe the array of two attributes. <code>bufferCount = 1</code> and <code>buffers = &vertex_layout</code> are added to the pipeline’s vertex stage. Buffer slot zero describes one stream of interleaved position/color records. It is independent of shader locations zero and one. Multiple attributes can come from the same buffer slot, as they do here.`))
  + s('Allocate once, upload once', q(9,"src/renderer.odin","    renderer.vertex_buffer =","    source :=","src/renderer.odin · renderer_init · allocate and upload vertex data","Inside renderer_init, insert this block at the beginning of the body, immediately before source :=. Keep the shader and pipeline setup that follows.")
  + p(`<code>.Vertex</code> allows vertex fetch from the buffer. <code>.CopyDst</code> allows writes through the queue. Flags are capabilities of the resource, not the operation we happen to perform first. Leaving out CopyDst is a validation error when uploading, even if the buffer size is correct. Buffer allocation by itself does not copy our constant into GPU storage.`)
  + p(`<code>QueueWriteBuffer</code> copies the supplied CPU bytes into implementation-managed upload storage as part of the call, with the GPU-visible write ordered through the queue. The local <code>vertices</code> copy exists to supply an addressable range for that call; it can go out of scope afterward. We do not map the vertex buffer, block for GPU completion, or retain a pointer to the local array. The data size is 72 bytes, a multiple of four, satisfying the write operation’s alignment requirement.`)
  + p(`Add a vertex-buffer handle to <code>Renderer</code> and release it in <code>renderer_destroy</code>. Inside <code>renderer_frame</code>, bind slot zero immediately after selecting the pipeline and before drawing:`)
  + code('wgpu.RenderPassEncoderSetVertexBuffer(pass, 0, renderer.vertex_buffer, 0, size_of(VERTICES))', 'odin', 'src/renderer.odin · renderer_frame · insert between SetPipeline and Draw')
  + p(`The byte offset is zero and the bound range is the whole vertex array. This establishes which actual buffer supplies the slot whose layout the pipeline already describes. Layout and binding solve different questions: “how are records interpreted?” versus “which storage contains them?”`))
  + s('Interpolate values across the triangle', p(`WGSL can return a struct, just as Odin can. Vertex_Out groups the clip position and a color in one result. The local out value is declared with var because the function assigns its fields before returning it. The location numbers connect the vertex result to the fragment input.`)
  + q(9,'shaders/character.wgsl')
  + p(`The vertex shader returns a struct with a built-in clip position and a user color at location zero. The fragment shader receives the interpolated color at that location. Do not confuse its location zero with the vertex input color at location one: these are different stage interfaces. Locations connect outputs to inputs at a particular stage boundary, not a single global namespace.`)
  + p(`Interpolation computes values between the ones supplied at the corners. Halfway along an edge between red and blue corners, the interpolated color is an equal mixture. Interior points combine contributions from all three corners. WGSL normally accounts for perspective during interpolation; here every w is one, so those contributions vary linearly across the triangle. The smooth colors are calculated during drawing, not stored as extra vertices.`))
  + frame([['Create vertex buffer and upload constant geometry', 'Once', 'Geometry remains unchanged across frames'], ['Describe layout', 'Pipeline creation', 'Fix the byte interpretation'], ['Bind vertex buffer', 'Every draw setup', 'Supply the pipeline’s vertex slot'], ['Interpolate color', 'GPU rasterization', 'Generate smooth values across coverage']])
  + mistakes([['Exploding or stretched geometry', 'Stride, offsets, bound range, position format', 'The GPU may be reading color bytes as a position'], ['Flat unexpected color', 'Stage locations and color input format', 'Correct bytes can still be routed to the wrong shader input'], ['WriteBuffer validation error', 'CopyDst, size, and four-byte alignment', 'The upload has requirements independent of vertex fetch']])
  + experiments(['Give all three vertices the same color. The interpolator is still active, but interpolation between equal values is constant.', 'Deliberately change the stride to 16 and inspect the first validation error or broken image. Restore 24 and explain the address of the second position in each case.']));

chapter(10, 'four-corners-six-indices', 'III · Build a small 2D renderer', 'Four corners, six indices',
  'The character starts as a rectangle. Reuse its corners instead of duplicating them.',
  'A green rectangle is drawn with four vertices and six u16 indices.',
  s('One shape, two triangles', p(`A triangle list consumes vertex references three at a time. Drawing four sequential vertices would create only one complete triangle and leave a remaining vertex without two partners. A rectangle requires six references: three for one triangle and three for the other. We can upload six full vertex records, or upload four records and an index buffer specifying how to reuse them.`)
  + d.quad + p(`Our index order is 0,1,2 followed by 0,2,3. Corners zero and two belong to both triangles. If we move corner zero in the vertex array, both triangles use the changed position. The vertex array answers “what is each corner?” and the index array answers “which corners form each triangle?”`))
  + s('Replace the triangle data', p(`In <code>renderer.odin</code>, replace <code>VERTICES</code> with four corners and add <code>INDICES</code>. Leave the vertex struct, vertex layout, and shader interfaces unchanged. This consistency is the point: the pipeline understands records and topology, not a hard-coded triangle asset.`)
  + q(10,"src/renderer.odin","VERTICES ::","Renderer ::","src/renderer.odin · replace vertex data; add indices","At file scope, replace the existing VERTICES declaration and add INDICES immediately after it, before Renderer. Keep Vertex and its assertions.")
  + p(`The first vertex is the upper-left in the current NDC arrangement. Positive y is upward at this stage, so the top corners use +0.35. We will replace these raw normalized positions with human-friendly coordinates in the next chapter. The chosen values are temporary and depend on window aspect ratio; they do not claim that the rectangle is a particular number of pixels wide.`)
  + p(`Add <code>index_buffer: wgpu.Buffer</code> to <code>Renderer</code>, then create and upload it after the vertex buffer. Each u16 index is two bytes. Six indices occupy 12 bytes, which also satisfies the four-byte write-size requirement. Not every odd-length array of u16 values would satisfy that upload requirement without padding, even though its individual indices are legal.`)
  + q(10,"src/renderer.odin","    renderer.index_buffer =","    source :=","src/renderer.odin · renderer_init · add index buffer","Inside renderer_init, insert this block after the vertex-buffer QueueWriteBuffer call and before source :=. Keep the vertex-buffer setup and shader setup.")
  + p(`The buffer usage is <code>.Index</code> plus <code>.CopyDst</code>. An index buffer and a vertex buffer share the same underlying WebGPU buffer object type; their usage flags and the commands binding them assign different roles. We do not use a special GPU allocation API called “create index buffer.” Descriptors configure the role of a general buffer.`))
  + s('Replace the draw, not the pipeline', code(`wgpu.RenderPassEncoderSetPipeline(pass, renderer.pipeline)
wgpu.RenderPassEncoderSetVertexBuffer(pass, 0, renderer.vertex_buffer, 0, size_of(VERTICES))
wgpu.RenderPassEncoderSetIndexBuffer(pass, renderer.index_buffer, .Uint16, 0, size_of(INDICES))
wgpu.RenderPassEncoderDrawIndexed(pass, 6, 1, 0, 0, 0)`, 'odin', 'src/renderer.odin · renderer_frame · replace the old three-vertex draw block')
  + p(`<code>DrawIndexed</code> takes index count, instance count, first index, base vertex, and first instance. Count six means six index entries, not six unique vertices. First index zero begins at the start of the bound index stream. Base vertex zero adds nothing to each fetched index before vertex fetch. The bound index format must match the uploaded representation: reading u16 data as Uint32 would combine pairs of indices into unrelated numbers.`)
  + p(`Keep the pipeline’s TriangleList setting and leave its strip-index format undefined. TriangleList groups each three index entries into one triangle. We are not selecting a different way of assembling connected triangles, so the existing pipeline setting remains correct.`)
  + p(`The GPU uses an index to select a vertex record, fetches that record’s attributes, executes the vertex shader as needed, and assembles triangles in the given order. The six references do not imply six distinct stored records or guarantee exactly six hardware vertex-shader executions. Reuse is an implementation optimization behind the API’s observable behavior.`))
  + s('Winding is a convention, not an outline', p(`A triangle’s winding is the order its corners appear around its perimeter. With back-face culling enabled, reversing that order can remove a triangle. We intentionally cull neither face while learning 2D coordinates. This avoids having a later y-axis flip silently hide the rectangle. It does not disable clipping; geometry outside the clip volume is still clipped.`)
  + p(`Add the matching index-buffer release to <code>renderer_destroy</code>. The buffer remains unchanged for all future character frames. Moving the character will not require rebuilding its index list: the topology stays the same when the same corners are translated.`))
  + frame([['Index allocation and upload', 'Once', 'Rectangle topology is stable'], ['Set index buffer and indexed draw', 'Every frame', 'Reference the corners in triangle order'], ['Rebuild pipeline', 'Not for this data change', 'Vertex format, topology, and attachment format are unchanged']])
  + mistakes([['Only half the rectangle appears', 'Index count and both index triplets', 'A rectangle needs two complete triangles'], ['Wild positions or a validation error', 'Uint16 versus Uint32 and index range', 'Each decoded index must select a valid bound vertex'], ['A triangle vanishes after enabling culling', 'Winding before and after the coordinate conversion', 'The y flip changes orientation']])
  + experiments(['Change the second triangle to 0,1,3. Sketch the resulting coverage before running it; two arbitrary triangles need not cover the desired rectangle.', 'Switch all four vertex colors to distinct values. Find the diagonal by observing the interpolation gradient rather than a drawn edge.']));

chapter(11, 'coordinates-for-humans', 'III · Build a small 2D renderer', 'Coordinates measured in pixels',
  'Replace aspect-dependent normalized geometry with a position and a size you can reason about.',
  'A 48 × 64 rectangle appears at framebuffer position (120,100), using a temporary CPU transform.',
  s('The problem with moving in NDC', p(`An NDC x distance of one spans half the window width; an NDC y distance of one spans half its height. In a wide window those distances represent different pixel counts. Defining a character as “0.2 by 0.2” therefore does not define a square on screen. NDC is useful as the pipeline’s common coordinate language, but it is inconvenient as our game’s measurement system.`)
  + p(`We want an upper-left position of (120,100), a width of 48, and a height of 64. Begin with local corners (0,0), (1,0), (1,1), (0,1). A local coordinate describes a point relative to the character itself. Multiplying by size gives a displacement from its origin; adding position puts it in the world. For now the world is measured in framebuffer pixels, and its origin is the window’s top-left.`)
  + d.transforms)
  + s('Derive the conversion rather than memorize it', p(`For x, dividing pixel_x by the width W maps the left and right boundaries to 0 and 1. Multiplying by two maps them to 0 and 2. Subtracting one produces −1 and +1. For y, dividing by height H also gives 0 at the top and 1 at the bottom. We want +1 at the top and −1 at the bottom, so use one minus twice that fraction.`)
  + code(`pixel = position + local_position * size
ndc_x = 2 * pixel_x / W - 1
ndc_y = 1 - 2 * pixel_y / H`, 'text', 'The coordinate contract; the executable Odin version follows below')
  + d.coordinates
  + table(['Pixel position in 960 × 640', 'NDC', 'Interpretation'], [['(0,0)', '(−1,+1)', 'Upper-left image boundary'], ['(480,320)', '(0,0)', 'Image center'], ['(960,640)', '(+1,−1)', 'Lower-right boundary'], ['(120,100)', '(−0.75,+0.6875)', 'Character upper-left'], ['(168,164)', '(−0.65,+0.4875)', 'Character lower-right']])
  + p(`Width and height appear independently in the formula, which corrects aspect ratio without a separate aspect-ratio multiplier. A 48-pixel horizontal span maps to a different NDC span than a 48-pixel vertical span in a nonsquare window, and that is exactly what keeps the displayed dimensions correct. No matrix is needed to express scale, translation, and this projection.`))
  + s('Make the data local, then transform a copy', p(`In <code>renderer.odin</code>, replace only the four positions in <code>VERTICES</code> with the local unit-square corners. Keep the colors, vertex ABI, index array, and pipeline unchanged. At the beginning of <code>renderer_frame</code>, after confirming a usable surface extent, add this temporary transform and upload:`)
  + q(11,"src/renderer.odin","    // Temporary:","    frame :=","src/renderer.odin · renderer_frame · add CPU coordinate transform","Inside renderer_frame, insert this block after the gpu_refresh_surface guard and before frame := wgpu.SurfaceGetCurrentTexture. Keep the acquisition and rendering code that follows.")
  + p(`The constant <code>VERTICES</code> remains local geometry. Each frame starts with a fresh copy and transforms that copy. Transforming the already transformed previous-frame positions would accumulate scale and translation and quickly send the rectangle off screen. The local data and the projected output have different meanings even though both use two floating-point components.`)
  + p(`The buffer still has CopyDst usage from its original upload, so updating it is permitted. We overwrite its 96 bytes with projected positions and original colors. Queue ordering places that write before the submitted draw. The vertex shader still returns its input position with z=0 and w=1. The GPU therefore sees exactly the NDC values we computed on the CPU.`)
  + note('Deliberately temporary code', 'This per-frame vertex rewrite exists to make the coordinate transformation concrete. Chapter 12 removes it and moves the same arithmetic into the vertex shader. Do not optimize it away before you can predict the four output corners. The complete checkpoint here is runnable as written.'))
  + s('Pixels, edges, and clipping', p(`The character’s upper-left position describes a boundary, not a pixel center. Integer-aligned edges at (120,100) and (168,164) cover the expected interior sample centers for an unrotated rectangle. Subpixel movement can move an edge between those centers, and a single-sampled hard-edged shape can appear to step between coverage changes. Frame-rate-independent motion does not guarantee antialiased edges. We intentionally do not add multisampling to address that separate topic.`)
  + p(`A negative world x moves part of the character outside the window; the normal clip process trims the visible triangles. We do not need CPU-side clipping to keep GPU output within the attachment. Later we will clamp game position so the user can keep the character visible, which is a gameplay choice rather than a rendering safety requirement.`)
  + p(`This chapter uses framebuffer pixels intentionally. Once high-density windows are enabled, we will choose SDL logical window units for game measurements and retain physical pixels for surface configuration. The formula remains the same, but W and H will refer to the logical world extent. That change will be explicit, not a silent reinterpretation of position.`))
  + frame([['Local geometry upload', 'Initially', 'Same indexed unit rectangle'], ['CPU transform and 96-byte write', 'Every frame, temporarily', 'Demonstrate position-to-NDC correspondence'], ['Draw and presentation', 'Every rendered frame', 'Use the updated vertex buffer']])
  + mistakes([['Rectangle shrinks or flies away over time', 'Transforming a fresh local copy', 'Projecting previously projected positions compounds transforms'], ['Shape stretches with window aspect', 'Separate W and H divisors', 'A common divisor gives different unit scales across axes'], ['Positive y moves up', 'The y projection sign', 'Window y and NDC y point in opposite directions']])
  + experiments(['Change position to (0,0). The top-left edges should coincide with the drawable boundaries.', 'Make the size (64,64) and the window wide. Predict why it is still square.', 'Move the rectangle partly outside the left edge. Explain why the GPU can clip triangles without game code clipping the rectangle.']));

chapter(12, 'uniforms-and-bindings', 'III · Build a small 2D renderer', 'Let the vertex shader place the character',
  'Keep the local corners fixed and let the shader calculate their displayed positions.',
  'The same rectangle is positioned by WGSL using a 48-byte uniform and an explicit bind group.',
  s('What changes and what stays the same', p(`The unit-square vertices and six indices never change when our character moves. Only position, size, view extent, camera offset, and tint vary. Rather than rewrite vertex records, we can provide those few values through a uniform buffer: a GPU-readable resource whose values are shared by shader invocations for a draw.`)
  + p(`“Uniform” describes how the shader accesses this data, not a claim that the bytes can never change. We will write fresh values each frame. The pipeline’s resource contract remains fixed, the bind group continues to refer to the same buffer, and the buffer contents change. This distinction is the practical reason WebGPU separates layouts, bindings, and resources.`))
  + s('Specify the host/shader memory contract', p(`Add <code>Uniforms</code> and its assertions in <code>renderer.odin</code>. Add the corresponding WGSL struct at the top of the shader, before <code>Vertex_Out</code>. Unlike the vertex layout, uniform memory layout is defined by WGSL’s host-shareable type rules, not by an array of vertex attributes.`)
  + p(`Alignment is a rule about where a value may start in memory. If a field needs 16-byte alignment, its offset within this block must be a multiple of 16. Padding is unused space inserted to satisfy such rules. Our four pairs occupy bytes 0 through 31, leaving the four-component tint correctly aligned at byte 32. The table below checks every field.`)
  + q(12,"src/renderer.odin","Uniforms ::","Renderer ::","src/renderer.odin · add the 48-byte uniform ABI","At file scope, add Uniforms and its assertions after INDICES and before Renderer. Keep the existing vertex declarations.")
  + q(12,"shaders/character.wgsl","struct Uniforms","struct Vertex_Out","shaders/character.wgsl · add the uniform resource","At the top of the shader, add the Uniforms struct and its group-0/binding-0 resource declaration before struct Vertex_Out. Keep the remaining shader declarations.")
  + table(['Member', 'Odin bytes', 'WGSL alignment / size'], [['position', '0–7', 'vec2f: align 8, size 8'], ['size', '8–15', 'vec2f: align 8, size 8'], ['view_size', '16–23', 'vec2f: align 8, size 8'], ['camera', '24–31', 'vec2f: align 8, size 8'], ['tint', '32–47', 'vec4f: align 16, size 16'], ['Whole struct', '48 bytes, host alignment 16', 'Struct extent rounded to its required alignment']])
  + p(`The four vec2f fields use 32 bytes, and the vec4f tint uses 16 more, making 48. Odin’s #align(16) gives the host struct the required alignment. The size and offset assertions check that its memory matches the WGSL struct. When changing a field’s type, recalculate both layouts before uploading the new data.`)
  + p(`There is also an alignment rule for the start of a uniform buffer binding. Our binding begins at byte zero, which satisfies it. We can allocate exactly 48 bytes for this block; we do not need to round the allocation up to 256. Member offsets inside the struct and the start of the buffer range are separate checks.`))
  + s('Describe the interface, then attach actual storage', p(`Add <code>uniform_buffer</code> and <code>bind_group</code> handles to <code>Renderer</code>. In <code>renderer_init</code>, replace the empty pipeline-layout construction with this sequence. The shader module already exists at this point; the final render pipeline is created afterward.`)
  + p(`Consider the shader declaration @group(0) @binding(0). It requests one numbered resource slot. The bind group layout describes what that slot accepts: a uniform buffer readable by the vertex shader, with at least 48 bytes. The bind group fills that slot with our actual buffer. The pipeline layout puts that group layout at group number zero. These descriptions let WebGPU check that the shader and the supplied buffer agree before drawing.`)
  + q(12,"src/renderer.odin","    renderer.uniform_buffer =","    if layout == nil","src/renderer.odin · renderer_init · replace the empty resource interface","Inside renderer_init, replace the empty layout := wgpu.DeviceCreatePipelineLayout declaration with this block. Keep the following if layout == nil check, deferred layout release, and pipeline setup.")
  + table(['Object', 'Question it answers', 'Dependency'], [['Uniform buffer', 'Where do the 48 bytes live?', 'Device'], ['Bind group layout', 'Which binding numbers, resource kinds, visibility, and minimum sizes are permitted?', 'Device and shader contract'], ['Bind group', 'Which actual buffer/range fills binding zero?', 'Layout plus uniform buffer'], ['Pipeline layout', 'Which bind group layout is group zero?', 'Ordered list of bind group layouts'], ['Render pipeline', 'Which shaders and fixed state use that resource interface?', 'Pipeline layout, shader stages, target configuration']])
  + p(`The layout entry’s <code>binding = 0</code> matches WGSL <code>@binding(0)</code>. Vertex visibility means the vertex stage may read it; our fragment stage consumes the interpolated tinted color instead of directly accessing the buffer. The entry’s buffer type is Uniform, with a minimum binding size of 48. The bind group then attaches the actual buffer at byte offset zero with range 48. It does not copy the uniform bytes or freeze their current value.`)
  + p(`The pipeline layout contains one layout at array position zero, which matches <code>@group(0)</code>. That position is the group number; it is not the binding number within the group. Both happen to be zero because we have exactly one of each. If the interface is wrong, pipeline validation or draw validation can reject the shader/resource combination before it accesses arbitrary memory.`))
  + s('Move the arithmetic, preserve the result', p(`Remove the temporary CPU vertex transform and its per-frame vertex upload. Replace that section of <code>renderer_frame</code> with a uniform value and write. The one-time vertex upload in <code>renderer_init</code> stays; it now holds unit-square local positions for every frame.`)
  + q(12,"src/renderer.odin","    uniforms :=","    frame :=","src/renderer.odin · renderer_frame · replace the temporary vertex rewrite","Inside renderer_frame, replace the temporary CPU vertex-transform block and its QueueWriteBuffer call with this uniform block. It belongs after the gpu_refresh_surface guard and before frame := wgpu.SurfaceGetCurrentTexture.")
  + q(12,'shaders/character.wgsl','fn vs_main')
  + p(`WGSL now performs the same multiply/add and pixel-to-NDC conversion as the previous CPU code. Subtracting <code>camera</code> defines a simple translation-only camera: if the camera moves right, a stationary world object appears farther left. Its default is (0,0). The multiply, add, and subtract operations express the transform we need.`)
  + p(`Immediately after setting the pipeline, add <code>RenderPassEncoderSetBindGroup(pass, 0, renderer.bind_group)</code>. The call binds actual resources to group zero for the upcoming draw. Native descriptor pointers can expire after creation, but the returned bind group and the uniform buffer must remain usable for subsequent frames. Release the bind group and buffer in <code>renderer_destroy</code>. Our references to the group layout and pipeline layout can be released at the end of initialization.`))
  + s('One write does not wait for one draw', p(`<code>QueueWriteBuffer</code> orders the data update before the next submission on that queue. Reusing this uniform buffer across successive frames is valid under that ordering. Do not insert a GPU-wide wait just to “make sure the new position arrived.” Conversely, writing two object transforms before a single submission does not make two draws automatically remember different versions: both draws can observe the last data written before them in queue order. For two objects, separate uniform buffers and bind groups would give each draw its own values. We will solve the multiple-object problem when the project needs it. For this chapter there is one draw and one update.`)
)
  + frame([['Uniform allocation, layouts, bind group', 'Initialization', 'Stable resource interface and storage'], ['Write 48 uniform bytes', 'Every rendered frame', 'Transfer changing position and view information'], ['Set bind group', 'Per draw setup', 'Connect the pipeline interface to actual resources'], ['Vertex transform', 'GPU vertex stage', 'Turn stable local geometry into this frame’s clip positions']])
  + mistakes([['Character vanishes when uniforms are introduced', 'Host offsets, WGSL layout, binding range, and group selection', 'A zero or misplaced view_size can invalidate every transformed coordinate'], ['Validation says binding not visible', 'Vertex stage visibility', 'The layout is permission for stage access'], ['Movement later changes CPU position only', 'The per-frame uniform write', 'Changing an Odin struct does not alter GPU storage automatically']])
  + experiments(['Set camera to (100,0). Predict the character’s displayed x without changing its world position.', 'Set tint to (1,0.5,0.5,1). Explain why the bind group need not be recreated.', 'Compare the four projected corners with chapter 11. The arithmetic moved to the GPU; the intended positions did not change.']));

chapter(13, 'resize-without-stretching', 'III · Build a small 2D renderer', 'Resize without stretching',
  'A desktop window has a logical size and a drawable pixel size. Give each number the right job.',
  'The window resizes and supports high-density displays while the character keeps its logical size and proportions.',
  s('Two sizes are both correct', p(`On a high-density display, a 960 × 640 SDL window can have a drawable image of 1920 × 1280 pixels. The logical size describes the desktop window’s coordinate extent. The physical size describes the image we render. Feeding 960 × 640 into the surface configuration would allocate or request the wrong drawable extent. Feeding 1920 × 1280 into a projection meant for logical game units would make a 48-unit character appear half as wide relative to the window.`)
  + p(`We now define one game unit as one SDL logical window unit. The upper-left remains (0,0), and positive y remains downward. The camera and character position use those units. WebGPU surface dimensions remain physical pixels. The vertex shader maps logical positions to NDC using the logical view extent; the viewport then maps NDC into the full physical attachment.`)
  + table(['Quantity', 'Query or source', 'Consumer'], [['Logical width and height', '<code>SDL_GetWindowSize</code>', 'Uniform view_size and later movement bounds'], ['Framebuffer width and height', '<code>SDL_GetWindowSizeInPixels</code>', 'SurfaceConfigure and implicit full attachment viewport'], ['Character position and size', 'Game values in logical units', 'Uniforms and vertex transformation'], ['Framebuffer coverage', 'Viewport mapping', 'Rasterizer output sample locations']])
  + p(`A 48-unit character in a 960-unit-wide window spans 48/960 of the window width. With a 1920-pixel attachment that is 96 physical pixels; with a 960-pixel attachment it is 48. In both cases its fraction of the logical window is identical. A logical square stays square under the ordinary uniform display scale. We do not need to multiply character coordinates by a scale factor and then accidentally apply that scale twice.`))
  + s('Enable resizing and use the right extent', p(`In <code>main</code>, replace the initial empty window flags with <code>{.RESIZABLE, .HIGH_PIXEL_DENSITY}</code>; preserve the macOS Metal flag addition. Handle <code>.WINDOW_PIXEL_SIZE_CHANGED</code> and <code>.WINDOW_RESTORED</code> by setting <code>gpu.dirty = true</code>. These events request a refresh. The actual dimensions still come from SDL when preparing the next frame, which naturally coalesces several resize events.`)
  + code(`flags: sdl.WindowFlags = {.RESIZABLE, .HIGH_PIXEL_DENSITY}
when ODIN_OS == .Darwin { flags += {.METAL} }`, 'odin', 'src/main.odin · main · replace flags initialization')
  + p(`In <code>gpu_refresh_surface</code>, add an early return for a minimized window before querying drawable dimensions. We already skip zero or over-limit dimensions and already reconfigure only on a changed extent or dirty flag. Add the logical size query in <code>renderer_frame</code> and use it in the uniform. This query will move to main when main begins coordinating game updates in chapter 14.`)
  + q(13,"src/renderer.odin","    width, height:","    frame :=","src/renderer.odin · renderer_frame · replace uniform view extent","Inside renderer_frame, replace the uniforms declaration and its QueueWriteBuffer call with this block, after the gpu_refresh_surface guard and before frame := wgpu.SurfaceGetCurrentTexture.")
  + p(`The import <code>core:c</code> supplies <code>c.int</code> for SDL’s output pointers. SDL writes C integer dimensions into those locals. Converting them to f32 happens only after checking for a positive extent. That check prevents division by zero in the shader as well as a nonsensical game view.`))
  + s('A resize has an ownership boundary', flow('Resize is applied between frame lifetimes.', ['Release old frame', 'Query sizes', 'Configure if needed', 'Acquire new image', 'Draw'])
  + p(`No prior acquired texture or view survives a completed <code>renderer_frame</code> call. The next call refreshes the configuration first and acquires afterward. Reconfiguration replaces the presentation images internally; it does not mean destroying and recreating the SDL window or the WebGPU device. We preserve the format, so the existing pipeline remains compatible.`)
  + p(`The shader’s new view extent is written every rendered frame. Resizing therefore changes both the backing image extent and the projection’s logical denominator when needed. If only the display scale changes, the physical extent may change while the logical extent remains the same; that is still handled because the surface refresh queries physical pixels independently.`)
  + p(`Minimized or zero-sized windows suspend rendering. SDL events and WebGPU completion processing continue in the outer loop, and a short sleep prevents spinning. We do not call SurfaceConfigure with zero dimensions, do not acquire from an unusable extent, and do not pretend the last valid image size is the current game view. Restoration triggers or naturally detects a usable extent and resumes drawing.`))
  + s('Viewport and scissor have separate jobs', p(`The implicit viewport covers the render attachment, and the default scissor permits the full attachment. To render into a smaller viewport you would explicitly call <code>RenderPassEncoderSetViewport</code> after beginning the pass. That rescales and relocates NDC. <code>RenderPassEncoderSetScissorRect</code> instead restricts framebuffer writes without changing the transformation. Both use physical framebuffer coordinates; neither changes the surface’s allocation.`)
  + code(`wgpu.RenderPassEncoderSetScissorRect(pass, 0, 0, gpu.config.width / 2, gpu.config.height)`, 'odin', 'src/renderer.odin · renderer_frame · optional: insert after pass setup and before the draw')
  + p(`The scissor will clip the character where it crosses the midpoint, while its apparent size remains the same. The load-operation clear is an attachment operation and is not limited by this later draw scissor. Restore the full scissor or remove the experiment before continuing. We do not add permanent viewport/scissor calls merely to restate the defaults.`))
  + frame([['Query drawable and logical dimensions', 'Each attempted frame', 'Observe size and display-scale changes'], ['SurfaceConfigure', 'Only on changed dimensions or dirty state', 'Update presentable image extent'], ['Uniform write', 'Each rendered frame', 'Use the current logical projection'], ['Rebuild buffers or pipeline', 'Never for size-only changes', 'Their layouts and formats remain valid']])
  + mistakes([['Character becomes tiny on a Retina display', 'Using physical extent for logical game coordinates', 'The projection denominator is twice as large'], ['Stretched or clipped image after resize', 'Surface extent and fresh projection extent', 'Updating only one side leaves the two contracts inconsistent'], ['Validation error while minimized', 'Zero-size and minimized guards before acquisition', 'No renderable image extent exists in that state']])
  + experiments(['Resize the window horizontally without changing its height. The character should remain 48 × 64 logical units, not stretch with the window.', 'Move the window between displays with different scaling, if available. Log both SDL sizes and compare them.', 'Try the scissor call above, then remove it. Explain why the background still clears across the entire image.']));

chapter(14, 'give-it-game-state', 'IV · Move one character', 'Give the program game state',
  'The renderer knows how to draw a position. The game decides which position and color to draw.',
  'Holding WASD or arrow keys changes the rectangle’s tint, proving the input-to-GPU path before movement.',
  s('Put meaning on the CPU side', p(`A WebGPU buffer contains values a shader needs. It should not be the only record of where the character is. Game state belongs to the CPU simulation, where input and movement rules can update it without depending on WebGPU handles. Rendering receives a snapshot of the values it needs and translates those into the uniform buffer.`)
  + p(`Add <code>src/game.odin</code>. Its <code>Game</code> struct contains position, size, and tint. The file also contains a small SDL input adapter and the game update procedure; four directions need only a small input procedure. The state and update parameters remain independent of WebGPU. <code>game_update</code> does not acquire images, create buffers, or know what a bind group is.`)
  + q(14,'src/game.odin','Game ::')
  + p(`Initialize <code>game</code> in <code>main</code> after renderer initialization with position (120,100), size (48,64), and white tint. The renderer no longer manufactures these values. Its arguments become <code>position</code>, <code>size</code>, <code>tint</code>, and <code>view_size</code> in addition to its connection and resource owners. The renderer receives only the values it draws.`))
  + s('Held keys are state, not repeated key-down events', q(14,'src/game.odin','read_movement ::')
  + p(`Call this after draining SDL events. <code>GetKeyboardState(nil)</code> returns a pointer to SDL’s keyboard-state array, whose lifetime SDL manages. We read it during this iteration and never free or modify it. The scancode enum indexes physical key positions. This is appropriate for movement controls; text entry would use different SDL facilities. W and the up arrow both contribute negative y, because our logical game coordinates increase downward.`)
  + p(`The horizontal axis adds one for right and subtracts one for left. Opposite directions cancel. Testing D or the right arrow with a boolean OR means holding both does not double speed. Keyboard auto-repeat is irrelevant: a held key is sampled as down each iteration. A very short press and release both processed before sampling might not be observed as held; discrete actions such as “jump once” often use key-down events instead. Our movement needs continuous held state.`)
  + p(`When the window lacks input focus, return zero direction. This prevents the character from continuing under an input state sampled while another window is active. SDL continues to own focus and event handling. We do not poll platform-specific keyboard APIs behind its back.`))
  + s('First prove the path with color', q(14,'src/game.odin','game_update ::')
  + p(`This update intentionally does not move anything yet. It sets a visible tint while a nonzero direction is held. A stationary colored rectangle is easier to diagnose than a moving object with a broken time unit. The next chapter removes this temporary tint-only update and replaces it with delta-time movement. Do not carry both updates forward accidentally.`)
  + p(`Move the logical window-size query from <code>renderer_frame</code> to <code>main</code>, after event processing. Main now needs that extent to coordinate update and render. Remove <code>core:c</code> from renderer imports and add it to main. The physical framebuffer-size query remains in <code>gpu_refresh_surface</code> because it configures GPU presentation. Nothing changes in the uniform byte layout or bind group.`)
  + q(14,"src/main.odin","        width, height:","        if !renderer_frame","src/main.odin · main loop · add input and update before rendering","Inside main, insert this block in the running loop after if gpu_failed() { break } and before the renderer_frame call. Replace that render call with the next snippet.")
  + code('if !renderer_frame(&gpu, window, &renderer, game.position, game.size, game.tint, view_size) { break }', 'odin', 'src/main.odin · main loop · replace the render call')
  + p(`Inside <code>renderer_frame</code>, replace fixed uniform position, size, tint, and view extent with those parameters. The camera stays zero. The shader still multiplies vertex color by tint, so the changed CPU game value reaches the fragment output through the existing uniform upload and interpolation path.`))
  + s('Why this loop order works', flow('Each frame uses state derived from the latest processed input.', ['SDL events', 'Keyboard state', 'Game update', 'Uniform write', 'Draw / present'])
  + p(`Processing events first makes the keyboard sample current and observes shutdown before further work. Updating next establishes the game state for this iteration. Rendering afterward presents that updated state. If render ran before update, the visible image would lag one simulation iteration behind the sampled input. The GPU may still execute asynchronously, but the CPU’s intended data ordering is now straightforward.`)
  + p(`A render skip does not inherently mean game state must freeze. This chapter skips update when the logical extent is zero or the window is minimized, because our world is the visible window and there is nothing useful to interact with then. Surface timeouts can skip only presentation. The next chapter will ensure that neither case creates a large accumulated time step when drawing resumes.`))
  + frame([['Read held keys', 'Each active iteration after events', 'Convert SDL state to a direction vector'], ['Update game tint', 'Each active iteration, temporarily', 'Prove input reaches the render data'], ['Upload uniforms', 'Each rendered frame', 'Copy the current game snapshot to the GPU'], ['Create bind group or pipeline', 'No change', 'Changing content is not changing an interface']])
  + mistakes([['No response to a held key', 'Focus and polling order before GetKeyboardState', 'Keyboard state is maintained by SDL event processing'], ['Game tint changes in a log but not on screen', 'Renderer parameters and uniform assignment', 'A stale literal can disconnect game state from rendering'], ['Color remains changed after release', 'Resetting tint before the conditional each update', 'A per-frame proof should reflect current input, not remembered input']])
  + experiments(['Hold opposite directions. The tint should return to its neutral state because the direction sums to zero.', 'Hold D and the right arrow together. Verify that the computed x direction is still one.', 'Temporarily change the tint in main after update. Explain why that value wins for this frame’s render snapshot.']));

chapter(15, 'movement-in-seconds', 'IV · Move one character', 'Movement measured in seconds',
  'Speed is a distance per unit time. A frame is not a unit of time.',
  'WASD and arrow keys move the character at 240 logical units per second, with equal diagonal speed.',
  s('A distance for this iteration', p(`If we add four units every frame, the character travels 240 units per second at 60 frames per second and 576 at 144. That ties gameplay to presentation frequency. Instead define a speed in logical units per second and multiply by elapsed seconds: distance = speed × dt. The GPU does not need to understand time; it only receives the resulting position.`)
  + p(`Add <code>speed: f32</code> to Game and set it to 240 in main. Record <code>previous_ticks := sdl.GetTicksNS()</code> immediately before the loop. After draining events and checking running, measure the new timestamp, compute elapsed seconds, and advance the previous timestamp. A nanosecond is one billionth of a second. The timestamps are integers; f64 converts their difference to a 64-bit floating-point value. Divide by one billion to get seconds, and min chooses the smaller of that result and 0.05. Subtract in integer nanoseconds before converting; converting two large uptime values to f32 before subtraction would lose useful precision.`)
  + code(`now := sdl.GetTicksNS()
dt := min(f64(now - previous_ticks) / 1_000_000_000.0, 0.05)
previous_ticks = now`, 'odin', 'src/main.odin · main loop · add after checking running')
  + p(`The timestamp update occurs before minimized/zero-size early continues. Time does not accumulate unnoticed while the window is suspended. The 0.05-second maximum prevents a debugger pause or long window drag from producing a huge jump. This is a deliberate policy: very long stalls discard elapsed simulation time, so the program slows relative to wall time during those stalls. “Frame-rate independent” means ordinary uncapped steps integrate a speed in seconds; it does not promise to replay every missed second under the cap.`))
  + s('Normalize intent before applying speed', p(`Replace the temporary tint-only <code>game_update</code> in <code>game.odin</code> with the movement procedure below. Add <code>core:math</code> for the square root. In main, pass <code>f32(dt)</code> and <code>view_size</code> to this procedure. All other input and render ordering stays the same.`)
  + q(15,'src/game.odin','game_update ::')
  + p(`A direction of (1,0) has length one. A direction of (1,1) has length √2, which would make diagonal movement faster. Divide a nonzero direction by its length before multiplying by speed and time. Check for nonzero length first: normalizing (0,0) would divide by zero and contaminate position with invalid values that can later make all geometry disappear.`)
  + p(`At 60 Hz, dt is about 1/60 second and a cardinal step is 4 units. At 144 Hz, it is about 1.667 units. After one second of steady input, both advance approximately 240 units. The use of floating-point positions allows fractional steps; converting position to an integer every update would discard small movements and reintroduce frame-rate-dependent errors.`)
  + table(['Scenario', 'Direction after normalization', 'Distance at dt = 1/60'], [['D', '(1,0)', '4 units right'], ['W', '(0,−1)', '4 units up'], ['D + S', '(0.7071,0.7071)', '4 units along the diagonal'], ['D + A', '(0,0)', '0'], ['A one-second stall', 'Whatever input is sampled now', 'At most 12 units due to the 0.05-second cap']]))
  + s('Keep the character reachable', p(`After applying motion, clamp the top-left x to [0, view_width − character_width] and y similarly. This keeps the whole rectangle inside the logical window when the window is large enough. If the window is smaller than the character, the maximum becomes negative; taking max with zero makes the permitted position zero instead. The character then extends outside the tiny window and is normally clipped.`)
  + p(`This clamp is a game rule, not a GPU requirement. Removing it would let the character leave the visible area. It also repositions the character if a resize makes its old position invalid. An application with a larger persistent world would likely keep world position and move a camera instead; our intentionally window-sized project uses the simplest explicit behavior.`)
  + p(`The renderer receives the updated position and writes it to the uniform buffer. Local vertices stay the unit square. The vertex shader computes four new clip positions, and rasterization covers a different set of samples. No texture is slid across the desktop and no previously drawn pixels are moved. Every frame clears and draws the character again at its current position.`))
  + s('Timing and GPU synchronization are different problems', p(`Delta time measures the CPU application’s iteration interval using SDL’s clock. It is not the GPU execution duration, the number of presented refreshes, or a fence. Submission and presentation may apply backpressure, which becomes part of the elapsed interval measured on the next iteration. We do not divide by an assumed monitor refresh rate or use a hard-coded 1/60 in the real application.`)
  + p(`For this application, each update uses the measured dt. The 0.05-second cap keeps a pause from becoming a large movement jump. It does discard time after a long stall, so the simulation will not cover the full real-world elapsed interval in that case. This is a responsiveness choice, not a promise of identical results under every timing condition.`)
)
  + frame([['Measure elapsed time', 'Each loop iteration', 'Keep suspended frames from accumulating a large step'], ['Integrate normalized direction', 'Each active update', 'Convert speed per second into position'], ['Clamp position', 'After movement', 'Keep the character visible in the current logical view'], ['Upload and transform', 'Each rendered frame', 'Make this CPU position determine new coverage']])
  + mistakes([['Movement is thousands of times too fast', 'Nanoseconds-to-seconds conversion', 'Speed uses seconds, not milliseconds or nanoseconds'], ['Diagonal motion is faster', 'Normalization before speed multiplication', 'Two unit axes combine to length √2'], ['Nothing moves at high frame rate', 'Floating-point position and dt calculation', 'Integer truncation can erase small increments'], ['Large jump after restoring', 'Timestamp advancement before skipped updates', 'Elapsed time should not accumulate across suspended iterations']])
  + experiments(['Change speed to 120. It should take about twice as long to cross a fixed distance during ordinary running.', 'Compare motion with and without a short artificial delay at the end of the loop. Below the stall cap, fewer frames should produce larger steps and a similar distance per second.', 'Temporarily remove normalization and compare cardinal and diagonal travel distances. Restore it before continuing.']));

chapter(16, 'color-alpha-character', 'IV · Move one character', 'Color, alpha, and a face',
  'Give the rectangle a face, then make transparency an explicit pipeline decision.',
  'A green geometric character with eyes and a mouth moves around the window; its pipeline supports straight-alpha blending.',
  s('A recognizable character needs very little art', p(`Our application already meets the movement goal. We will add a face without introducing texture loading, sampling, or an asset pipeline. The local unit-square coordinates give each fragment a useful location within the character. The fragment shader can test a few small rectangles for eyes and a mouth and choose a dark color for those regions.`)
  + p(`This is still triangle rendering. The face does not create more vertices or separate draw calls. The rasterizer covers the same two triangles, while the fragment shader chooses different colors within their coverage. The GPU’s geometry and coloring responsibilities are now especially easy to distinguish.`))
  + s('Pass local position through the rasterizer', p(`In <code>shaders/character.wgsl</code>, add <code>@location(1) local_position: vec2f</code> to <code>Vertex_Out</code>. In <code>vs_main</code>, assign <code>out.local_position = position</code> before returning. This is the original local position from the vertex buffer, not the clip position. The rasterizer interpolates it across the rectangle, producing values approximately in [0,1] inside the character.`)
  + q(16,'shaders/character.wgsl','fn fs_main')
  + p(`The eye and mouth tests operate in character-local fractions, so the features follow position and scale automatically. At x=0.29 and y=0.32, for example, a fragment lies inside the left eye. A fragment at the center of the body falls through to the interpolated body color. Because both triangles agree on local corner values, the diagonal does not interrupt the face.`)
  + p(`The dark face color uses the same alpha as the body. If we later make the character partially transparent, the eyes and mouth remain part of the same opacity convention. These tests have hard edges at single-sample coverage; we do not claim they provide analytic antialiasing. The aim is a simple recognizable figure, not a shader-art system.`))
  + s('Alpha is an input to a composition rule', p(`An alpha value of 0.5 does not inherently mean “show half the background.” With blending disabled, writing RGBA (green,0.5) can replace the previous target value, including its alpha. To combine the character color with the cleared background, the pipeline must enable a blend state.`)
  + p(`We use straight alpha: the shader’s RGB values are unmultiplied colors, and alpha separately describes their opacity. For source color Cs, destination color Cd, and source alpha As, the RGB equation is <code>Cs × As + Cd × (1 − As)</code>. The output alpha is <code>As + Ad × (1 − As)</code>. The background starts with alpha one, so the resulting window image remains alpha one.`)
  + p(`For example, take a red source (1,0,0) with alpha 0.5 over opaque blue (0,0,1). Half the source plus half the destination gives linear RGB (0.5,0,0.5). The output alpha stays 1. The blend descriptor below expresses those same multiplications and addition; its color and alpha factors differ because the two equations differ.`)
  + code(`blend := wgpu.BlendState{
    color = {operation = .Add, srcFactor = .SrcAlpha, dstFactor = .OneMinusSrcAlpha},
    alpha = {operation = .Add, srcFactor = .One, dstFactor = .OneMinusSrcAlpha},
}
target := wgpu.ColorTargetState{
    format = gpu.config.format, blend = &blend, writeMask = {.Red, .Green, .Blue, .Alpha},
}`, 'odin', 'src/renderer.odin · renderer_init · replace the previous ColorTargetState')
  + p(`The color and alpha components have different source factors. Multiplying source alpha by itself would give As² rather than As in the alpha equation. Premultiplied alpha would instead supply RGB already multiplied by alpha and normally use source factor One for color too. Both conventions can work; mixing straight shader output with premultiplied blend factors gives the wrong result.`)
  + p(`Blending is part of the pipeline because it affects output compatibility and fixed backend state. The descriptor’s blend pointer is local CPU input read during pipeline creation. Changing a local BlendState after the pipeline was created does not mutate that pipeline. Changing the character’s tint alpha, on the other hand, changes uniform data and needs no new pipeline.`))
  + s('Color encoding does not replace blending', p(`Our surface target is sRGB. The shader works with linear RGB values; the attachment handles sRGB storage conversion. Blend calculations use the appropriate linear color values. If you put a familiar sRGB display value such as 0.5 directly into the shader, you are specifying linear 0.5, which displays much brighter than an sRGB-encoded 0.5 swatch. For these chosen geometric colors, we define the numbers as linear from the outset.`)
  + p(`Surface composite alpha remains separate: it controls the whole window image’s relationship with the desktop compositor. Our opaque background ensures that window image is opaque. The character’s blend alpha only combines it with pixels already in our own attachment. You can make the character translucent without making the desktop visible through the window.`)
  + p(`Ordering matters when transparent objects overlap. A source-over blend can give a different result when you reverse draw order. We have one character over a cleared background, so the order is completely explicit and no sorting system is needed. The internal shared triangle edge follows rasterization coverage rules; it is not two full-opacity layers painted on top of each other.`))
  + s('Check the face and opacity separately', p(`Build and run with the normal tint alpha of 1. The eyes and mouth should move with the body. Then temporarily change the initial tint alpha in main to 0.5. The background should show through the entire character, including the face. Restore alpha 1 before continuing. This separates a coordinate error, where the face moves incorrectly, from a blending error, where opacity behaves incorrectly.`))
  + frame([['Create blending pipeline', 'Initialization', 'Fix the source-over output rule'], ['Interpolate local coordinates', 'GPU rasterization', 'Locate fragments within the character'], ['Choose face/body color and blend', 'Per fragment', 'Compute and combine the visible color'], ['Set tint alpha', 'Uniform update when desired', 'Change opacity without changing pipeline state']])
  + mistakes([['Lower alpha has no visible effect', 'Whether the pipeline target has a blend state', 'Alpha alone does not request composition'], ['Dark halos or bright transparency', 'Straight versus premultiplied RGB convention', 'Shader values and blend factors must agree'], ['Face sticks to the window while body moves', 'Which coordinates the fragment shader uses', 'Character-local coordinates move with the geometry']])
  + experiments(['Set game tint alpha to 0.5 in main, rebuild, and inspect the background showing through the character. Restore one for the final baseline.', 'Move one eye by changing its local x interval. Observe that no vertex data changes.', 'Set source color factor to One while keeping straight output and alpha 0.5. Predict the overly bright contribution, then restore SrcAlpha.']));

chapter(17, 'lifetimes-and-debugging', 'IV · Move one character', 'Lifetimes, failures, and debugging',
  'Check that each resource has an owner and is released, even when a step fails.',
  'The completed moving-character program is unchanged; we audit its ownership and failure policies.',
  s('Two kinds of lifetime must agree', p(`The application owns native references. The implementation owns backend objects and retains what submitted work needs. These lifetimes overlap, but are not identical. A local pointer variable going out of scope does not automatically release a native object. Calling Release decrements an application reference; it is not a synchronous command that frees all backend memory immediately.`)
  + p(`Destroy has a different meaning for resources such as buffers: it explicitly invalidates the resource for future use and schedules its storage for reclamation when safe. It is not a substitute for releasing the native handle. This program generally uses Release when its owner is finished. It never calls TextureDestroy on a borrowed-current presentation image in place of presenting and releasing it.`)
  + table(['Resource', 'Our lifetime', 'Cleanup boundary'], [['SDL window', 'Application', 'After GPU/surface/view teardown'], ['Metal view on macOS', 'Window’s surface lifetime', 'After surface release, before window destruction'], ['Instance, adapter, device, queue', 'Application', 'GPU owner cleanup'], ['Surface', 'Window', 'Unconfigure, then release'], ['Shader module', 'Renderer initialization', 'After pipeline creation'], ['Bind group layout / pipeline layout', 'Renderer initialization references', 'After dependent objects have been created'], ['Pipeline, vertex/index/uniform buffers, bind group', 'Many frames', 'Renderer cleanup'], ['Acquired texture and view', 'One frame', 'After submission/presentation or early exit'], ['Encoder, pass encoder, command buffer', 'One frame', 'At renderer_frame return'], ['Native capability arrays', 'Capability query scope', 'SurfaceCapabilitiesFreeMembers']]))
  + s('Read the cleanup we already wrote', q(18,'src/renderer.odin','renderer_destroy ::')
  + q(18,'src/gpu.odin','gpu_destroy ::')
  + p(`Main registered GPU cleanup before renderer cleanup, so the renderer’s defer runs first. Releasing renderer references does not invalidate work already submitted by the preceding frame; the backend retains its in-flight dependencies. GPU cleanup then drains queued work, unconfigures the surface, and releases queue/device/adapter references. Finally the platform owner releases the surface and its Metal view, and the earlier main defers destroy the window and quit SDL.`)
  + p(`The cleanup procedures check each handle and reset their owner struct afterward. That accommodates an initialization failure halfway through renderer setup. Native Release functions generally do not accept nil as a harmless no-op, so each check matters. The error flag stays valid until the process ends, including while cleanup may trigger callbacks. A normal device-destroyed loss reason is ignored; actual failures are reported.`)
  + p(`We wait at shutdown for simplicity, not once per frame. A per-frame DevicePoll with wait=true would turn the CPU/GPU pipeline into a serial handshake. It is valid to wait when the CPU genuinely needs a completed GPU result, such as a readback operation. Our moving rectangle never reads GPU memory back, so normal rendering needs queue ordering, not a CPU completion fence.`))
  + s('A failure policy is part of the implementation', table(['Failure', 'Implemented behavior', 'Reason'], [['SDL init/window failure', 'Print SDL error and return', 'No usable native window'], ['Instance/surface failure', 'Print stage; clean partial state', 'Cannot establish presentation connection'], ['Adapter/device failure', 'Print callback status/message; stop', 'No usable graphics connection'], ['Unsupported surface format', 'Explain required sRGB formats; stop', 'Do not silently change the color contract'], ['Zero/minimized/over-limit extent', 'Skip and briefly sleep; keep pumping', 'Wait for a usable window extent'], ['Timeout or occlusion', 'Skip current presentation attempt', 'May be transient'], ['Outdated', 'Mark dirty and retry next iteration', 'Refresh presentation configuration'], ['Suboptimal success', 'Render now, refresh next iteration', 'Image usable but configuration should be renewed'], ['Surface lost', 'Log and stop; restart required', 'Recreating the window/surface connection is not attempted'], ['Device loss / uncaptured error', 'Log, set atomic fault, stop', 'Old device resources cannot be assumed usable'], ['Present failure', 'Log and stop', 'Do not silently keep presenting an invalid chain']])
  + note('Know the limits of error recovery', 'This edition reports and exits on device or surface loss. It does not promise transparent GPU recovery. Native wgpu-native can also treat certain invalid-handle/API misuse paths as fatal before ordinary callbacks can recover. Guards, correct descriptors, and pinned API verification remain necessary.'))
  + s('Debug from the last fact you can prove', p(`For a black window, first choose a conspicuous clear color. If that appears, acquisition, attachment setup, and submission/presentation have worked for that frame. Next use the constant-color triangle checkpoint. If that works but the final character does not, the first differences to inspect are vertex layout, indices, uniform layout, and transform values. An error message often names the resource and the rule it broke. Read that first message before changing other code.`)
  + p(`For a character that does not move, inspect the chain in order: direction after SDL polling, dt in seconds, game.position after update, uniform.position before QueueWriteBuffer, and the shader’s usage of that field. If CPU position changes but uniform.position remains a literal, the GPU is correctly rendering stale data. Rebuilding pipelines or changing presentation modes cannot repair that disconnected value.`)
  + p(`For distorted geometry, calculate the byte address of vertex one’s position from stride and offset. Compare it with the actual struct assertions. Check whether the index format matches u16. Then calculate the character’s four NDC corners from position, size, and view extent. A known correct byte layout plus known correct corners makes a shader/pipeline problem much more specific than “graphics are broken.”`)
  + p(`Use labels already attached to resources: “character uniforms,” “character pipeline,” and “window color pass” turn backend diagnostics into references to our application. Error scopes can isolate expected validation experiments, and GPU capture tools can inspect submitted work, but neither is required to reason through this small pipeline. Temporarily add targeted logs rather than printing every field every frame and burying the first useful error.`))
  + s('An orderly frame is the cheapest lifetime check', p(`Count the per-frame creates and acquisitions, then their matching releases. A successful render creates a view, encoder, pass, and command buffer and obtains a texture reference. Each has exactly one cleanup on every subsequent exit path. The persistent objects have no per-frame creation sites. Memory that grows without bound after thousands of frames is therefore a reason to inspect the native reference paths before inventing an allocator system.`)
  + p(`No implementation changes are introduced in this chapter. Your files remain as they were at the end of chapter 16. Reviewing the existing lifetimes is a finished capability: you can now explain why returning from a frame is safe while the GPU might still be busy, and why descriptor locals can disappear even though their created objects survive.`))
  + frame([['Ownership audit', 'Development time', 'Check one matching release per owned reference'], ['Per-frame native releases', 'Every attempted frame with acquired objects', 'Bound CPU/native object lifetimes'], ['GPU-wide wait', 'Shutdown only', 'Orderly teardown without serializing all frames']])
  + mistakes([['Treating Release as a GPU wait', 'Whether completion is actually required', 'Reference ownership and queue completion are separate'], ['Freeing capability pointers with Odin delete', 'Native allocator ownership', 'The allocation did not come from Odin’s allocator'], ['Retry loop after surface loss', 'The explicit fatal Lost branch', 'Reconfiguration is not guaranteed to rebuild a lost platform connection']])
  + experiments(['Temporarily break the uniform minimum size and observe which labeled validation diagnostic appears. Restore the valid layout before continuing.', 'Walk every return path in renderer_frame and mark the resources alive at that point. Check that their defers cover them.', 'Minimize and restore repeatedly. The application should remain responsive and avoid configuring zero-sized images.']));

chapter(18, 'from-main-to-pixels', 'IV · Move one character', 'From a key press to a presented image',
  'Follow one key press from the game update to the image shown in the window.',
  'You can trace the geometric character from keyboard input through the game update and GPU work to the displayed image.',
  s('The foundation main is the map', p(`There are no new code changes. The application is unchanged from chapter 17. Its complete files appear below. Keep working in your own project; this chapter reviews the geometric character before we add pictures. Start at main, then follow a single key press through the CPU and GPU. Every helper now names machinery we have already implemented and examined.`)
  + q(18,'src/main.odin')
  + p(`The startup order follows dependencies. SDL must exist before its window. The instance must exist before the surface. The surface participates in compatible-adapter selection. The adapter creates a device, and the device supplies a queue. The adapter/surface capabilities and device limits determine configuration. The renderer then creates stable geometry, a shader module, uniform storage, resource layouts, a bind group, and a compatible pipeline. Game state can be initialized independently, but it has no visible effect until a frame uploads it.`))
  + s('Startup creates the objects a frame needs', d.objects + flow('Startup establishes the objects that survive many frames.', ['SDL window', 'Instance / surface', 'Adapter / device', 'Queue / config', 'Renderer resources'])
  + p(`The instance is our native implementation context; it is not the hardware. The adapter represents a compatible candidate; the device is the logical resource-owning connection created from it. The queue orders writes and submissions. The surface wraps the native presentation destination. Its configuration defines the images we can acquire, including a format the pipeline must match.`)
  + p(`The renderer’s descriptors form two connected contracts. The vertex layout reads each 24-byte Odin record as Float32x2 position and Float32x4 color at locations zero and one. The resource contract maps group zero, binding zero to a 48-byte uniform range. A pipeline layout describes that group interface; the bind group attaches actual storage. The pipeline selects WGSL entry points and fixes triangle topology, blending, sample count, and color target format. None of those objects encodes this frame’s position.`))
  + s('Trace one press of D', flow('The position that changes pixels has a visible route through the program.', ['D held', 'Direction (1,0)', 'Position update', '48-byte upload', 'Vertex transform'])
  + p(`The operating system delivers keyboard information to SDL. Main drains SDL’s queued events, updating SDL’s keyboard state. If the window has focus, read_movement sees D down and returns (1,0), unless the opposite direction cancels it. Main measures dt in seconds. game_update normalizes the direction, multiplies by speed and dt, adds the displacement to game.position, and clamps the result to the logical window bounds.`)
  + p(`At an ordinary 60 Hz iteration with no clamp, position (120,100) becomes approximately (124,100). Main passes that value to renderer_frame. It is copied into Uniforms.position, and QueueWriteBuffer schedules the 48 bytes for the GPU buffer. The bind group still names the same buffer. The pipeline has not changed, the index buffer has not changed, and the unit-square vertices have not changed.`)
  + p(`During execution, the vertex shader fetches a local corner, such as (1,0), and computes (124,100) + (1,0) × (48,64) − (0,0) = (172,100). With a logical view width of 960, its NDC x is 2 × 172/960 − 1, approximately −0.641667. The top-left corner similarly moved from x=120 to x=124. All corners receive the same world translation, so the rectangle moves without changing shape.`)
  + p(`Clipping and the viewport convert those clip coordinates into covered framebuffer samples. The rasterizer interpolates color and local position across the triangles. The fragment shader chooses face or body colors. The blend state combines those colors with the background already cleared into the image. Presentation schedules that image for display. The image contains new pixels; no old character bitmap was physically relocated.`))
  + s('One complete frame, in exact order', table(['Step', 'Application operation', 'Consequence'], [
    ['1', 'Poll SDL events', 'Observe close, resize, and current keyboard state'],
    ['2', 'Measure dt; process WebGPU callbacks', 'Advance clock and observe native failures'],
    ['3', 'Query logical extent; read input; update game', 'Produce the CPU state to show'],
    ['4', 'Refresh physical surface configuration if necessary', 'Prepare a valid image extent before acquiring'],
    ['5', 'Write uniforms', 'Order the new position before the draw submission'],
    ['6', 'Acquire current surface texture', 'Obtain the presentable image for this frame'],
    ['7', 'Create its texture view', 'Describe the color attachment access'],
    ['8', 'Create command encoder and begin render pass', 'Record a pass that clears its attachment'],
    ['9', 'Set pipeline, bind group, vertex buffer, index buffer', 'Supply compatible executable state and resources'],
    ['10', 'DrawIndexed(6,1,0,0,0)', 'Record two triangles for one instance'],
    ['11', 'End pass and finish encoder', 'Produce a closed command buffer'],
    ['12', 'Submit to queue', 'Hand ordered work to the implementation'],
    ['13', 'Present surface', 'Hand the completed-image dependency to presentation'],
    ['14', 'Release frame-local references', 'End application ownership without forcing a GPU wait'],
  ]) + p(`Uniform upload appears before acquisition in our implementation. It could occur after successful acquisition as long as it is ordered before submission. A timed-out acquisition can therefore leave a harmless queued update without a draw; the next rendered frame overwrites it with current state. This is an implementation ordering choice, not an omitted upload or an immediate execution assumption.`)
  + p(`When a resize arrives, only the physical surface extent and logical projection values need updating. When the window is minimized, events and timing continue while drawing is suspended. When an unrecoverable GPU error occurs, the diagnostic flag ends the loop and cleanup releases the known owners. These are branches of the same frame lifecycle, not separate miniature renderers.`))
  + s('Answers you can now derive', table(['Question', 'Answer grounded in this program'], [['Why an adapter before a device?', 'Choose a surface-compatible capability provider before creating the resource-owning connection'], ['Why does the surface have a format?', 'Its images need a defined representation and color interpretation that the pipeline’s output matches'], ['Why locations and vertex layouts?', 'The GPU reads untyped bytes and must route decoded attributes into a particular shader interface'], ['Why encode instead of immediate drawing?', 'The implementation validates and batches coherent work while CPU and GPU proceed asynchronously'], ['Why acquire every frame?', 'The current presentation image is a frame-scoped resource managed by the surface'], ['Why two triangles?', 'TriangleList describes filled triangle coverage; six corner references cover the rectangle'], ['What moves the character?', 'A CPU position update becomes uniform bytes, then different clip positions and rasterized coverage'], ['What survives resizing?', 'Device, queue, pipeline, layouts’ retained dependencies, buffers, and bind group; only presentation extent and uniform view values change']]))
  + s('Keep this program small enough to understand', p(`The moving geometric character completes the foundation. A change in position reaches the screen through code you have now followed from input to presentation. Next, the room and player pictures will replace the shader-drawn face. We will keep the window, graphics connection, time-based movement, and cleanup rules and extend the drawing data to describe more than one picture.`))
  + frame([['Initialization', 'Once', 'Establish stable graphics contracts and native ownership'], ['Update and render', 'Repeated', 'Translate current input into visible geometry'], ['Reconfiguration', 'Only when extent/status requires it', 'Maintain presentation compatibility'], ['Cleanup', 'Once', 'Release owners in reverse dependency order']])
  + mistakes([['Adding a pipeline rebuild to fix stale position', 'Which object actually stores changing data', 'Uniform contents, not immutable pipeline state, hold position'], ['Changing world coordinates to repair DPI configuration', 'Separate logical and physical extents', 'The same formula serves both scales when each extent has the correct role'], ['Assuming a successful image proves all error paths', 'Resize, loss, and partial-init ownership', 'Normal rendering and failure handling require distinct evidence']])
  + experiments(['Starting at main, explain one D-key update without looking at the diagram. Name the exact point where CPU data is copied for the GPU.', 'Change the character’s size and verify that its face scales with it and movement bounds adapt. Identify the buffers that did not need recreation.', 'Return to the original triangle checkpoint and explain every object it lacks compared with the final program. Each missing object should solve a specific later need.']));

